/* techniques q06 (153 mục) — R6 sửa lỗi - gop trung 2026-07-26 - gop trung 2026-07-26 */
window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q06"]=window.__LIBQ["the-gioi-hoan-my"]["q06"]||{};window.__LIBQ["the-gioi-hoan-my"]["q06"]["techniques"]={"updatedAt":"2026-07-25","count":153,"techniques":[{"id":"bat-lao-tien-kinh","name":"Bất Lão tiên kinh","cn":"","loai":"cong-phap","loaiLabel":"Tiên kinh","phamCap":"Tiên kinh","hePhai":"Bất Lão Sơn","soHuu":["Bất Lão Thiên Tôn"],"blurb":"Tiên kinh do Bất Lão Thiên Tôn tụng niệm, có khả năng độ hóa chúng sinh và trấn áp đối thủ.","detail":"Khi Bất Lão Thiên Tôn thi triển, các ký hiệu trong kinh văn hóa thành những tòa thần sơn để độ hóa và trấn áp sinh linh bất diệt. Ngũ Hành Sơn còn hóa thành bảo ấn, gia trì uy lực kinh văn trong cuộc giao chiến.","nguon":["@c0501"]},{"id":"tran-phap-than-linh-bao-ve-vuon-thuoc","name":"Trận pháp thần linh bảo vệ vườn thuốc","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Thần linh","hePhai":"Bất Lão sơn","soHuu":["Bất Lão sơn"],"blurb":"Trận pháp che giấu khu vực trồng thánh dược và ngăn linh khí thoát ra ngoài.","detail":"Trận pháp bảo vệ khu vực trồng cây Ngũ nguyên trong vườn thuốc Bất Lão sơn. Tiểu Tháp chấn tan trận pháp rồi thu lấy vật liệu bố trận.","nguon":["@c0502"]},{"id":"kiem-khi-hon-don","name":"Kiếm khí hỗn độn","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"","soHuu":["Tiểu Tháp"],"blurb":"Luồng kiếm khí mang sức mạnh hỗn độn do Tiểu Tháp thi triển để phản kích Trượng Lục kim thân.","detail":"Sau khi bị khúc tre đánh trúng và ngã nhào, Tiểu Tháp tung kiếm khí hỗn độn đánh thẳng về phía Trượng Lục kim thân.","nguon":["@c0502"]},{"id":"phap-tuong-kim-than-ngan-tay","name":"Pháp tướng kim thân ngàn tay","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Cái thế","hePhai":"Tây Phương giáo","soHuu":["Tây Phương giáo chủ"],"blurb":"Thần thông hiện ra hơn ngàn cánh tay vàng, cho phép Tây Phương giáo chủ đồng loạt công kích Tiểu Tháp.","detail":"Khi thi triển, Tây Phương giáo chủ đẩy uy năng chiến đấu tới cực hạn, trong nháy mắt hiện ra hơn ngàn cánh tay vàng và khiến tất cả cùng đánh về một mục tiêu.","nguon":["@c0503"]},{"id":"quy-tac-hon-don","name":"Quy tắc hỗn độn","cn":"","loai":"khac","loaiLabel":"Pháp tắc","phamCap":"","hePhai":"Hỗn độn","soHuu":["Tiểu Tháp"],"blurb":"Quy tắc được Tiểu Tháp bí mật bố trí trong mục tiêu rồi kích nổ từ bên trong.","detail":"Tiểu Tháp bố trí quy tắc hỗn độn trong Trượng lục kim thân khi tạm thời nuốt đối phương. Lúc quy tắc bùng nổ, hư không sụp đổ và pháp quang quanh kim thân gần như biến mất.","nguon":["@c0503"]},{"id":"ky-tran-bao-ho-cua-tieu-thap","name":"Kỳ trận bảo hộ của Tiểu Tháp","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"","soHuu":["Tiểu Tháp"],"blurb":"Những kỳ trận từ thân Tiểu Tháp có thể bao phủ và chuyển cả một khu vực khỏi Bảo giới.","detail":"Tiểu Tháp thả các kỳ trận xuống mặt đất, bao phủ khu vực có cha mẹ Thạch Hạo rồi khiến toàn bộ khu vực ấy biến mất khỏi giới, tránh khỏi dư ba của cuộc đại chiến.","nguon":["@c0503"]},{"id":"truong-luc-kim-than","name":"Trượng lục kim thân","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"Tây Phương giáo","soHuu":["Tây Phương giáo chủ"],"blurb":"Thần thông gia trì kim thân của Tây Phương giáo chủ, có thể diễn hóa thành hình thái ngàn tay để công kích.","detail":"Tây Phương giáo chủ vận dụng Trượng lục kim thân giao chiến với cành liễu của Liễu Thần, sau đó diễn hóa thành Kim thân ngàn tay lấp lánh như lửa thần để đối đầu sức mạnh từ thần bàn quanh Liễu Thần.","nguon":["@c0504"]},{"id":"tu-khi-dong-lai","name":"Tử khí đông lai","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"","soHuu":["Cường giả vô thượng cưỡi trâu"],"blurb":"Thần thông tạo tử khí và hình thành tràng vực quy tắc, dùng để phong ấn khu vực và bảo vệ người thi triển. (+) Đại thần thông được Tử Nhật Thiên Quân thi triển trong trận quyết đấu với Đường Ngô. [CAN-SOAT-GOP]","detail":"Cường giả vô thượng cưỡi trâu vận dụng tử khí hóa thành một vùng tràng vực quy tắc bao quanh bản thân, vừa phong ấn không gian xung quanh vừa gia trì phòng hộ khi giao chiến với cành liễu của Liễu Thần.","nguon":["@c0504","@c1316"],"tabs":{}},{"id":"than-ban-ba-ngan-gioi","name":"Thần bàn ba ngàn giới","cn":"","loai":"than-thong","loaiLabel":"Dị tượng thần thông","phamCap":"","hePhai":"","soHuu":["Liễu Thần"],"blurb":"Dị tượng gồm ba ngàn chùm sáng như ba ngàn thế giới hợp thành một vòng thần bàn bao phủ Liễu Thần.","detail":"Mỗi chùm sáng trong thần bàn tựa như một thế giới có thần linh tụng kinh và quỳ lạy Liễu Thần. Các thế giới hợp nhất thành vòng thần bàn hộ thân, đồng thời những thần linh bên trong có thể phóng bảo thuật để hợp kích đối thủ.","nguon":["@c0504"]},{"id":"ky-hieu-phan-ngu-hanh","name":"Ký hiệu phản ngũ hành","cn":"","loai":"bi-thuat","loaiLabel":"Thần văn","phamCap":"Không nêu","hePhai":"Không nêu","soHuu":["Liễu Thần"],"blurb":"Dấu ấn thần văn từ thời đại hỗn độn có khả năng phá và khắc chế lực ngũ hành.","detail":"Liễu Thần triển khai ký hiệu phản ngũ hành để phá chùm sáng của Ngũ hành sơn, uy hiếp chân thân ngọn núi và hấp thu một phần tinh khí ngũ hành.","nguon":["@c0505"]},{"id":"dao-sinh-truong","name":"Đạo Sinh trưởng","cn":"","loai":"than-thong","loaiLabel":"Đạo pháp","phamCap":"Không nêu","hePhai":"Không nêu","soHuu":["Liễu Thần"],"blurb":"Đạo pháp do Liễu Thần diễn hóa thành vô số thực vật cắm rễ trong hư không.","detail":"Những thực vật được tạo ra liên tục hấp thu lực ngũ hành và pháp lực của Trượng lục kim thân, qua đó phá thế phối hợp phong ấn giữa Ngũ hành sơn và Giáo chủ Tây Phương giáo.","nguon":["@c0505"]},{"id":"dao-hoa-dau-an-thien-dia","name":"Đạo hóa dấu ấn thiên địa","cn":"","loai":"than-thong","loaiLabel":"Đạo pháp","phamCap":"Không nêu","hePhai":"Không nêu","soHuu":["Cường giả vô thượng được tử khí bao quanh"],"blurb":"Đạo pháp giúp người thi triển hóa thành nhiều dấu ấn thiên địa xuất hiện khắp bốn phương.","detail":"Cường giả tử khí hóa thành khí trong suốt rồi hiện ra vô số bóng người. Mỗi bóng là một ký hiệu cầm tiên kiếm, đồng loạt phát động công kích nhằm vào Liễu Thần.","nguon":["@c0505"]},{"id":"bao-thuat-dung-hop-dao-con-bang","name":"Bảo thuật dung hợp đạo Côn Bằng","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"Không nêu","hePhai":"Không nêu","soHuu":["Liễu Thần"],"blurb":"Bảo thuật do Liễu Thần dung hợp đạo Côn Bằng với đạo pháp của bản thân, khiến mỗi đầu cành liễu hóa sinh một con Côn Bằng.","detail":"Hàng trăm nghìn cành liễu hóa thành xích thần trật tự, mang theo sức mạnh Côn Bằng phá tan thế công từ các dấu ấn thiên địa và chấn vỡ tiên kiếm của cường giả tử khí.","nguon":["@c0505"]},{"id":"dao-am-ba-nghin-than-linh-cung-bai","name":"Đạo âm ba nghìn thần linh cúng bái","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Không nêu","hePhai":"Không nêu","soHuu":["Liễu Thần"],"blurb":"Đạo âm làm hiện ra cảnh tượng ba nghìn thần linh cúng bái, đồng thời vang lên tiếng tế tự.","detail":"Liễu Thần dùng đạo âm và tiếng tế tự của ba nghìn thần linh để phá tan kim quang do pháp ấn mạnh nhất của Giáo chủ Tây Phương giáo phát ra.","nguon":["@c0505"]},{"id":"tran-truyen-tong-dien-dong-bat-lao-son","name":"Trận truyền tống của điện đồng Bất Lão sơn","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"Bất Lão sơn","soHuu":["Bất Lão sơn"],"blurb":"Trận pháp nằm trong điện đồng của Bất Lão sơn, tạo thành đường kết nối để đi tới thượng giới.","detail":"Khi Ngũ Hành sơn hóa thành khí bản nguyên và đi qua điện đồng để tới thượng giới, trận pháp nổ tung, khiến cung điện bằng đồng rung chuyển dữ dội.","nguon":["@c0506"]},{"id":"bao-thuat-chi-ton-cua-thach-hao","name":"Bảo thuật Chí tôn của Thạch Hạo","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Chí cường","hePhai":"Bảo thuật bản mệnh","soHuu":["Thạch Hạo"],"blurb":"Môn bảo thuật bản mệnh hình thành trong Chí tôn cốt, chỉ thuộc riêng Thạch Hạo.","detail":"Sau khi Chí tôn cốt hấp thu tinh hoa thạch nhũ, những phù văn phức tạp như thiên thư hiện rõ trên khối cốt. Bảo thuật đang dần thành hình nhưng chiêu thức và năng lực cụ thể chưa được bộc lộ.","nguon":["@c0507"]},{"id":"tran-phap-co-phong-an-to-dia-kim-o","name":"Trận pháp cổ phong ấn tổ địa Kim Ô","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Cổ xưa","hePhai":"Tộc Kim Ô","soHuu":["Tộc Kim Ô"],"blurb":"Trận pháp cổ từng phong ấn tổ địa Kim Ô và thần thổ thái cổ phía sau thành cổ.","detail":"Khi trận pháp giải thể, tổ địa bị phong ấn cùng biển dung nham rộng lớn xuất hiện, thu hút nhiều Tôn giả bản địa tới tìm kiếm cơ duyên.","nguon":["@c0507"]},{"id":"quy-tac-cam-khong-cua-bien-kim-o","name":"Quy tắc cấm không của biển Kim Ô","cn":"","loai":"khac","loaiLabel":"Cấm chế tự nhiên","phamCap":"","hePhai":"Biển Kim Ô","soHuu":[],"blurb":"Quy tắc bao phủ biển Kim Ô, ngăn cả Tôn giả phi hành trên biển dung nham.","detail":"Sinh linh cố bay vào khu vực này sẽ bị kéo xuống dung nham. Hươu năm màu cấp Tôn giả từng thử vượt qua nhưng bị nhiệt lực làm tổn thương và phải quay về bờ.","nguon":["@c0507"]},{"id":"than-thong-dieu-khien-bien-dung-nham","name":"Thần thông điều khiển biển dung nham","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Không rõ","hePhai":"Tộc Kim ô","soHuu":["Đạo nhân Kim ô thứ nhất"],"blurb":"Thần thông vận dụng địa thế biển lửa để điều khiển dung nham, dựng lên sóng lớn ngăn cản đối phương vượt biển.","detail":"Đạo nhân Kim ô thi triển bằng một động tác ấn tay, khiến sóng biển dung nham dâng cao ngợp trời và đánh về phía đoàn Ngân sư.","nguon":["@c0508"]},{"id":"luc-luong-nguyen-rua-thuyen-ma","name":"Lực lượng nguyền rủa thuyền ma","cn":"","loai":"bi-thuat","loaiLabel":"Nguyền rủa","phamCap":"Không rõ","hePhai":"Không rõ","soHuu":[],"blurb":"Lực lượng nguyền rủa bao phủ các cổ thuyền trên biển dung nham, giữ thi thể thái cổ không tiêu tan và biến chúng thành Quỷ thần binh.","detail":"Nguyền rủa mang khí tức âm trầm và khói đen, bảo tồn tử thi trên thuyền ma. Những thi thể chịu ảnh hưởng có thể đứng dậy chiến đấu, cầm binh khí và phóng ra ánh đen lạnh buốt.","nguon":["@c0508"]},{"id":"chu-tuoc-bao-thuat","name":"Chu tước bảo thuật","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Bảo thuật ngưng tụ Chu tước trong lòng bàn tay, có thể cuốn dung nham công kích nhiều đối thủ.","detail":"Thạch Hạo ngưng tụ một con Chu tước trong lòng bàn tay rồi điều khiển nó cuốn theo sóng dung nham, đánh về phía các Tôn giả Bảo giới thái cổ.","nguon":["@c0509"]},{"id":"bao-thuat-lam-long","name":"Bảo thuật Lam Long","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"","hePhai":"","soHuu":["Lam Long"],"blurb":"Bảo thuật của Lam Long có thể phối hợp với chuông đồng để tăng uy lực lên nhiều lần.","detail":"Lam Long thi triển bảo thuật công kích bầy đàn, đồng thời dùng chuông đồng ngân vang để hợp nhất và gia trì sức mạnh, khiến uy lực của bảo thuật tăng lên nhiều lần.","nguon":["@c0509"]},{"id":"phu-van-chi-ton-cot","name":"Phù văn Chí tôn cốt","cn":"","loai":"khac","loaiLabel":"Kinh văn · Trận pháp bản mệnh","phamCap":"","hePhai":"Chí tôn cốt","soHuu":["Thạch Hạo"],"blurb":"Hệ phù văn được gây dựng lại sau khi Chí tôn cốt của Thạch Hạo hoàn toàn tái sinh, trở nên phức tạp và khác lạ hơn trước.","detail":"Thạch Hạo chọn phù văn Chí tôn cốt làm trận pháp của bản thân, khắc vào từng tấc máu thịt và cả phủ tạng để tu luyện Liệt trận cảnh. Quá trình này giúp nó đột phá tới Liệt trận cảnh hậu kỳ và tăng cường lực chiến.","nguon":["@c0510","@c0572"],"tabs":{"tienTrinh":[{"chuong":"@c0572","loai":"thi triển","importance":"normal","giaiDoan":"Thử nghiệm minh văn toàn thân","text":"Thạch Hạo thử khắc phù văn Chí Tôn cốt vào huyết nhục và xương cốt, nhưng các phù văn đều bị bảo cốt hút trở lại.","anchor":"những phù văn này khi khắc vào thân thể và xương cốt thì sẽ bị Chí Tôn cốt hấp dẫn"}]},"trangThai":"Đang được thử nghiệm","congNang":["Khắc dấu năng lực Chí Tôn cốt lên huyết nhục và xương cốt."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0572","tangDatToi":"Đang thử nghiệm minh văn toàn thân","trangThai":"đang suy diễn"}]},{"id":"phu-van-xoa-diet","name":"Phù văn xóa diệt","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Chưa rõ","hePhai":"Chưa rõ","soHuu":["Thạch Hạo"],"blurb":"Một loại phù văn thần bí có khả năng xóa mục tiêu thành ánh sáng.","detail":"Thạch Hạo phóng ra một mảnh phù văn bao phủ đối thủ, khiến người này hóa thành ánh sáng rồi biến mất. Sức mạnh ấy đồng thời xóa mất một cánh tay của Trác Vân, khiến những người còn lại phải dè chừng.","nguon":["@c0512"]},{"id":"luan-hoi","name":"Luân Hồi","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Thần thông Chí tôn cốt","hePhai":"Chí tôn cốt","soHuu":["Thạch Hạo"],"blurb":"Bảo thuật dẫn ra xích thần trật tự chứa sức mạnh thời gian, có thể xuyên qua phòng ngự và khiến đối phương lão hóa hàng ngàn đến hàng vạn năm. (+) Thần thông phát sinh từ Chí tôn cốt của Thạch Hạo, có thể khiến mục tiêu già hóa và mất sinh cơ trong thời gian cực ngắn. [CAN-SOAT-GOP] (+) Thiên phú thần thông của Thạch Hạo được khắc họa trên Chí Tôn cốt, liên quan tới thời gian và Luân Hồi. [CAN-SOAT-GOP]","detail":"Khi được Thạch Hạo thử nghiệm trong màn sương, sức mạnh Luân Hồi phóng ra ánh sáng ký hiệu, giam cầm Quỷ đằng và đánh nát ba pháp khí của nó. Quỷ đằng suy kiệt như đã trải qua hàng nghìn năm, thân thể khô héo rồi hóa thành tro; qua lần thi triển này, Thạch Hạo hiểu thêm một cách vận dụng Chí tôn cốt.","nguon":["@c0513","@c0933","@c1282"],"tabs":{},"aliases":["Luân Hồi bảo thuật"]},{"id":"chi-ton-cot","name":"Chí tôn cốt","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Thần thông từ bảo cốt được Thạch Hạo vận dụng để nhanh chóng kết thúc cuộc giao chiến với Trác Vân và ba người đi cùng.","detail":"Thạch Hạo phối hợp sức mạnh Chí tôn cốt với pháp kiếm màu vàng khi giao chiến, khiến kiếm thể phát ra ký hiệu thần bí làm bốn mục tiêu trở về trạng thái trẻ dại cả về hình thể lẫn thực lực.","nguon":["@c0514"]},{"id":"hoa-tinh-thai-duong","name":"Hỏa tinh Thái dương","cn":"","loai":"khac","loaiLabel":"Thần hỏa","phamCap":"","hePhai":"Thái dương","soHuu":[],"blurb":"Thần hỏa màu vàng bảo vệ sinh linh trong quả trứng, có uy lực đủ thiêu diệt một Tôn giả.","detail":"Hỏa tinh Thái dương xuất hiện dưới dạng chùm sáng và ký hiệu vàng, làm một đầu của Rắn chín đầu suýt bị chém đứt và thiêu một Tôn giả thành tro bụi, hình thần đều diệt. Chưa xác định sức mạnh này phát ra từ quả trứng hay hoa hoàng kim.","nguon":["@c0514"]},{"id":"than-cong-su-tu-hong","name":"Thần công Sư tử hống","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Thần công","hePhai":"","soHuu":["Ngân sư"],"blurb":"Ngân sư phát tiếng rống tạo thành gợn sóng bạc, khiến cổ điện rung vang và khí hỗn độn dâng trào.","detail":"Âm thanh của Thần công Sư tử hống hóa thành gợn sóng bạc công kích Thạch Hạo, đồng thời khuấy động khí hỗn độn trong cổ điện.","nguon":["@c0515"]},{"id":"muoi-dong-thien-noi-lien","name":"Mười Động thiên nối liền","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"Động thiên","soHuu":["Thạch Hạo"],"blurb":"Mười Động thiên được đồng thời hiện ra và nối liền, có thể giam cầm hư không trong khoảnh khắc.","detail":"Thạch Hạo vận dụng thần thông này để khóa vùng hư không quanh thanh niên tóc tím, tạo cơ hội phá phòng hộ và kết liễu đối phương.","nguon":["@c0516"]},{"id":"kiem-khi-cay-co","name":"Kiếm khí cây cỏ","cn":"","loai":"kiem-quyet","loaiLabel":"Kiếm quyết","phamCap":"","hePhai":"Kiếm đạo","soHuu":["Thạch Hạo"],"blurb":"Một cây cỏ hiện ra rồi phóng kiếm khí bao phủ cả khu vực.","detail":"Thạch Hạo dùng kiếm khí phủ kín không gian, ép thanh niên tóc tím đang ẩn trong hư không phải lộ diện và khiến vai đối phương bị thương.","nguon":["@c0516"]},{"id":"tran-phap-quanh-ban-da","name":"Trận pháp quanh bàn đá","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"","soHuu":[],"blurb":"Trận pháp bao quanh bàn đá đặt cốt thư trong cổ điện Hỗn độn.","detail":"Huyết dịch kích hoạt trận pháp, khiến bàn đá và các phù văn xung quanh phát sáng, đồng thời mở ra khả năng dùng bảo thuật lấy cốt thư.","nguon":["@c0516"]},{"id":"than-hoa-phan-thien","name":"Thần hỏa phần thiên","cn":"","loai":"than-thong","loaiLabel":"Thần thông hỏa hệ","phamCap":"","hePhai":"Tộc Kim ô","soHuu":["Đạo nhân Kim ô"],"blurb":"Thần thông tạo ra ngọn lửa màu vàng nhằm thiêu đốt nguyên thần của đối phương.","detail":"Một đạo nhân Kim ô thi triển thần thông này khi nguyên thần Thạch Hạo bị lục lạc ép rời khỏi thân thể. Ngọn lửa vàng bao phủ người tí hon nguyên thần, định đốt nguyên thần thành tro.","nguon":["@c0517"]},{"id":"u-hoa-dia-nguc","name":"U hỏa địa ngục","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"","soHuu":["Lam long"],"blurb":"Thần thông hỏa diễm của Lam long, tạo ra ngọn lửa xanh lạnh lẽo được truyền là có thể thiêu đốt linh hồn.","detail":"Lam long thi triển U hỏa địa ngục để tập kích Thạch Hạo. Ngọn lửa có uy lực không kém tinh hỏa Thái dương, nhưng cuối cùng bị pháp môn Côn bằng chân chính với lực Thái âm và Thái dương đánh tan.","nguon":["@c0518"]},{"id":"tran-tu-tuong","name":"Trận Tứ tượng","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"","soHuu":[],"blurb":"Trận thế dùng để vây giết và hạn chế đường di chuyển của mục tiêu.","detail":"Đả Thần Thạch nhận diện được quy luật vận chuyển và các phương vị của Trận Tứ tượng, nhờ đó chỉ đường cho Thạch Hạo né tránh sát quang trong vòng vây.","nguon":["@c0519"]},{"id":"tran-ngu-hanh-cua-chien-dao","name":"Trận Ngũ hành của Chiến đảo","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"Tộc Người khổng lồ hoàng kim","soHuu":["Tộc Người khổng lồ hoàng kim"],"blurb":"Trận thế Ngũ hành của Chiến đảo có khả năng bao vây và phát ra sát quang.","detail":"Đả Thần Thạch nhìn thấu cửa ngõ của trận thế, hướng dẫn Thạch Hạo tiến vào cửa Kim rồi thoát ra từ cửa Hỏa để tránh các đợt công kích.","nguon":["@c0519"]},{"id":"tran-phap-khi-hon-don","name":"Trận pháp khí hỗn độn","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"","soHuu":[],"blurb":"Một tòa trận pháp tràn ngập khí hỗn độn, có khả năng niêm phong người ở bên trong.","detail":"Cha mẹ và đệ đệ của Thạch Hạo bị niêm phong trong trận pháp này. Thạch Hạo tìm tới nơi đặt trận sau khi phá vòng vây và rời chiến trường.","nguon":["@c0519"]},{"id":"tran-phap-hon-don-cua-tieu-thap","name":"Trận pháp hỗn độn của Tiểu Tháp","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"","soHuu":["Tiểu Tháp"],"blurb":"Trận pháp dùng khí hỗn độn bảo vệ và phong tỏa vùng núi nơi cha mẹ Thạch Hạo trú ẩn.","detail":"Do Tiểu Tháp bố trí, trận pháp có sức phòng hộ rất mạnh, ngay cả giáo chủ thượng giới cũng khó phá hỏng. Khi trở về, Tiểu Tháp thu lại pháp kỳ, hấp thu khí hỗn độn và giải trừ trận pháp.","nguon":["@c0520"]},{"id":"than-thai-tai-sinh","name":"Thần thai tái sinh","cn":"","loai":"cong-phap","loaiLabel":"Cổ pháp","phamCap":"","hePhai":"Bổ Thiên giáo","soHuu":["Nguyệt Thiền"],"blurb":"Cổ pháp cho phép thần thai niết bàn rồi phân thành chủ thân và thứ thân, để cả hai cùng tu hành và hỗ trợ phục sinh lẫn nhau.","detail":"Sau khi phân hóa, chủ thân và thứ thân đều có thể tu hành, đồng thời có thể dựa vào thân còn lại để phục sinh nếu một thân chết đi. Hai thân hợp nhất sẽ đạt trạng thái viên mãn; chủ thân mạnh hơn và có thể cảm nhận, chỉ đạo hoặc điều khiển thứ thân khi khoảng cách không quá xa. Khi thứ thân hiện hữu vẫn còn sống, chủ thân không thể tiếp tục lột xác để tạo ra một thân mới.","nguon":["@c0521"]},{"id":"tran-phap-phong-toa-than-thuc","name":"Trận pháp phong tỏa thần thức","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Trận pháp dùng để phong tỏa thần thức và khóa chặt một vùng không gian.","detail":"Thạch Hạo bố trí trận pháp này trong mật thất nhằm cô lập khu vực hành động, hỗ trợ hắn và Ma nữ tiến vào biển ý thức của Nguyệt Thiền.","nguon":["@c0522"]},{"id":"kiem-khi-thong-thien","name":"Kiếm khí thông thiên","cn":"","loai":"than-thong","loaiLabel":"Thần thông thần thức","phamCap":"","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Kiếm khí được diễn hóa trong biển ý thức để tấn công thần hồn đối phương.","detail":"Thạch Hạo thi triển kiếm khí thông thiên chém về phía Nguyệt Thiền trong cuộc chiến thần thức, nhưng toàn bộ kiếm khí bị chân long quanh người nàng tiêu diệt.","nguon":["@c0522"]},{"id":"chan-long-ho-than","name":"Chân long hộ thân","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật thần thức","phamCap":"","hePhai":"","soHuu":["Nguyệt Thiền"],"blurb":"Bảo thuật hiện hóa chân long quanh người để bảo vệ người thi triển và phá hủy thế công bằng kiếm khí.","detail":"Trong biển ý thức, một con chân long xuất hiện quanh Nguyệt Thiền, ngâm vang chín tầng trời rồi tiêu diệt toàn bộ kiếm khí do Thạch Hạo phát ra.","nguon":["@c0522"]},{"id":"than-chu-canh-hoa-khac-dao","name":"Thần chú cánh hoa khắc Đạo","cn":"","loai":"bi-thuat","loaiLabel":"Thần chú","phamCap":"","hePhai":"","soHuu":["Ma nữ"],"blurb":"Thần chú tạo ra những cánh hoa mang dấu ấn của Đạo để vây đánh thần hồn đối phương.","detail":"Ma nữ ngâm tụng thần chú trong biển ý thức, triệu hồi hàng loạt cánh hoa có khắc dấu Đạo và dùng uy năng của chúng bao phủ Nguyệt Thiền.","nguon":["@c0522"]},{"id":"tiet-thien-thuat","name":"Tiệt thiên thuật","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"","soHuu":["Ma nữ"],"blurb":"Bảo thuật trấn giáo được Ma nữ vận dụng để sát thương nhóm kỵ binh Thiên Thần. (+) Thần thông được Ma nữ sử dụng để phối hợp trấn áp và phong ấn Nguyệt Thiền. [CAN-SOAT-GOP]","detail":"Tiệt thiên thuật hóa thành một vệt sáng rực rỡ trong biển ý thức, kết hợp với pháp môn Côn bằng của Thạch Hạo khiến Nguyệt Thiền bị phù văn giam cầm và niêm phong hoàn toàn.","nguon":["@c0522","@c1045"],"tabs":{}},{"id":"nam-tang-tran-phap-than-linh","name":"Năm tầng trận pháp thần linh","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Thần linh","hePhai":"","soHuu":[],"blurb":"Hệ thống gồm năm lớp trận pháp thần linh chồng lên nhau, có khả năng phong tỏa toàn bộ khu vực.","detail":"Các ký hiệu phủ kín hư không rồi hình thành năm tầng trận pháp bao phủ lẫn nhau, phong tỏa nơi Thạch Hạo, Nguyệt Thiền và Ma nữ đang hiện diện. Người bố trí hoặc kích hoạt trận pháp chưa được xác định.","nguon":["@c0523"]},{"id":"bi-thuat-thu-than-cua-nguyet-thien","name":"Bí thuật thứ thân của Nguyệt Thiền","cn":"","loai":"bi-thuat","loaiLabel":"Bí thuật","phamCap":"Cổ pháp","hePhai":"Bổ Thiên giáo","soHuu":["Nguyệt Thiền"],"blurb":"Cổ pháp thần bí tạo nên thứ thân tách biệt với bản thể. Nguyệt Thiền đã tu thành bí thuật này.","detail":"Bí thuật cho phép người tu có bản thể và thứ thân. Nguyệt Thiền xuất hiện bên cạnh Thạch Hạo là thứ thân được tạo ra nhờ cổ pháp này, trong khi một thân khác của nàng vẫn còn tồn tại.","nguon":["@c0525"]},{"id":"chan-kinh-phan-tam-chua-ro-ten","name":"Chân kinh phân tâm chưa rõ tên","cn":"","loai":"cong-phap","loaiLabel":"Kinh pháp","phamCap":"Chưa rõ","hePhai":"Bổ Thiên giáo","soHuu":["Nguyệt Thiền"],"blurb":"Kinh pháp được Nguyệt Thiền âm thầm tụng niệm để phân tán tinh thần và chìm vào thế giới kinh văn.","detail":"Trong phòng tân hôn, Nguyệt Thiền dùng chân kinh này để giữ tâm trí tập trung vào kinh văn và duy trì vẻ trang nghiêm. Tên chính thức cùng phẩm cấp của kinh pháp chưa được xác định.","nguon":["@c0527"]},{"id":"thuat-xung-kich-phong-an-nguyen-than-chua-ro-ten","name":"Thuật xung kích phong ấn nguyên thần chưa rõ tên","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Chưa rõ","hePhai":"Bổ Thiên giáo","soHuu":["Nguyệt Thiền"],"blurb":"Thủ đoạn được Nguyệt Thiền vận dụng để thử xông khỏi phong ấn nguyên thần.","detail":"Nguyệt Thiền thúc động mi tâm và biển ý thức phát sáng, đồng thời phóng ra khí tức thần thánh nhằm phá phong ấn. Lần thử nghiệm không thành công, thần hồn của nàng vẫn không thể vận chuyển và sức chiến đấu chưa được khôi phục.","nguon":["@c0527"]},{"id":"tien-kinh-on-dinh-dao-tam","name":"Tiên kinh ổn định đạo tâm","cn":"","loai":"cong-phap","loaiLabel":"Công pháp","phamCap":"Chưa rõ","hePhai":"","soHuu":["Nguyệt Thiền tiên tử"],"blurb":"Tiên kinh được chủ thân Nguyệt Thiền tụng để tĩnh tâm và ổn định đạo tâm sau khi chặt đứt liên hệ với thứ thân.","detail":"Chủ thân Nguyệt Thiền dùng thần thức quan sát chân ngã và tụng tiên kinh nhằm bình ổn nội tâm, khôi phục trạng thái siêu nhiên không vướng bụi trần.","nguon":["@c0529"]},{"id":"dai-tran-trieu-hoan-thien-thach","name":"Đại trận triệu hoán thiên thạch","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Chưa rõ","hePhai":"","soHuu":["Nguyệt Thiền tiên tử"],"blurb":"Đại trận khổng lồ được chủ thân Nguyệt Thiền bố trí trên tầng mây để liên tục triệu hoán thiên thạch và núi lớn.","detail":"Trận pháp nằm sau lưng chủ thân Nguyệt Thiền, tạo thành thế công từ trên cao với nhiều thiên thạch, trong đó có cả những ngọn núi được triệu hoán từ Hoang vực.","nguon":["@c0529"]},{"id":"tran-phap-bao-ve-hoang-cung-thach-quoc","name":"Trận pháp bảo vệ hoàng cung Thạch quốc","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Chưa rõ","hePhai":"Thạch quốc","soHuu":["Thạch Hạo","Bằng Cửu"],"blurb":"Hệ thống trận pháp nhiều tầng bảo vệ các cung điện thượng cổ trong hoàng cung Thạch quốc.","detail":"Trận văn in vào hư không để ngăn mưa thiên thạch. Khi phòng tuyến bị đánh thủng tạo thành khe hở, Thạch Hạo dùng bảo ấn kích hoạt các tầng trận pháp khép lại; sau đó Bằng Cửu được giao chủ trì hệ thống này.","nguon":["@c0529"]},{"id":"tien-hoang-do-ruc","name":"Tiên hoàng đỏ rực","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Chưa rõ","hePhai":"","soHuu":["Nguyệt Thiền tiên tử"],"blurb":"Thần thông hóa ra một con tiên hoàng đỏ rực, có khả năng công kích và chém qua hư không.","detail":"Chủ thân Nguyệt Thiền phóng tiên hoàng từ trong cơ thể. Những chiếc lông đỏ của nó chém qua hư không, còn mục tiêu chủ yếu của đòn đánh là thứ thân Nguyệt Thiền đang ở trên lưng Thạch Hạo.","nguon":["@c0529"]},{"id":"bao-thuat-kinh-the-chua-ro-ten","name":"Bảo thuật kinh thế chưa rõ tên","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"Chưa rõ","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Một bảo thuật mạnh được Thạch Hạo thi triển khi chủ động phát động thế công.","detail":"Thạch Hạo xuất ra bảo thuật này giữa lúc ánh kiếm ngang trời nhằm trấn áp đối phương ở phía trước.","nguon":["@c0529"]},{"id":"kiem-khi","name":"Kiếm khí","cn":"","loai":"kiem-quyet","loaiLabel":"Thần thông kiếm đạo","phamCap":"","hePhai":"Kiếm đạo","soHuu":["Thạch Hạo"],"blurb":"Kiếm khí dày đặc có thể phá vỡ tấm khiên phù văn và gây thương tích cho đối thủ.","detail":"Thạch Hạo phóng ra lượng lớn kiếm khí, đồng loạt đánh lên tấm khiên do phù văn biến thành. Đòn công kích xuyên phá phòng ngự và để lại vết thương trên gương mặt chủ thân Nguyệt Thiền.","nguon":["@c0530"]},{"id":"co-phap-phan-tach-hai-than-thai","name":"Cổ pháp phân tách hai thần thai","cn":"","loai":"bi-thuat","loaiLabel":"Cổ pháp","phamCap":"Vô thượng","hePhai":"","soHuu":["Nguyệt Thiền"],"blurb":"Cổ pháp tạo ra chủ thân và thứ thân từ hai thần thai cùng nguồn gốc, nhưng quá trình phân tách để lại khiếm khuyết khó đảo ngược.","detail":"Sau khi bị phân tách, hai thần thai dần hình thành ý thức và nhận thức độc lập. Sự khác biệt giữa chúng khiến hai thân không thể hoàn toàn hợp nhất trở lại trạng thái ban đầu.","nguon":["@c0530"]},{"id":"than-phap-suc-dia-thanh-thon-cua-chu-than-nguyet-thien","name":"Thân pháp súc địa thành thốn của chủ thân Nguyệt Thiền","cn":"","loai":"than-thong","loaiLabel":"Thân pháp","phamCap":"Cấp cao nhất về phương diện tốc độ","hePhai":"","soHuu":["Chủ thân Nguyệt Thiền"],"blurb":"Thân pháp cực nhanh của chủ thân Nguyệt Thiền, được đặt ngang hàng với thần tốc Côn Bằng về phương diện tốc độ.","detail":"Chủ thân Nguyệt Thiền dùng thân pháp này để liên tục xuất kích và di chuyển với tốc độ cực hạn trong cuộc chiến với Thạch Hạo.","thuocTinh":"Tốc độ và dịch chuyển","congNang":["Giúp người thi triển di chuyển và xuất kích cực nhanh."],"nguoiTu":[{"ten":"Chủ thân Nguyệt Thiền","tuChuong":"@c0531","tangDatToi":"Chưa rõ","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0531","loai":"thi triển","importance":"normal","giaiDoan":"Đối đầu thần tốc Côn Bằng","text":"Chủ thân Nguyệt Thiền thi triển thân pháp cực hạn để giao chiến với Thạch Hạo.","anchor":"hai thân pháp này đều là cấp cao nhất trong thiên địa, được xưng là cực hạn trong phương diện này"}]},"capNhatToi":"@c0531","nguon":["@c0531"]},{"id":"than-thong-khai-thong-trang-bac","name":"Thần thông khai thông trăng bạc","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Chưa rõ","hePhai":"","soHuu":["Chủ thân Nguyệt Thiền"],"blurb":"Thần thông tiếp dẫn ánh trăng và thu nhận thần lực vô lượng.","detail":"Chủ thân Nguyệt Thiền khai thông trăng bạc để trói buộc chiến trường và gia trì sức mạnh mặt trăng cho bảo thuật chân long cùng thần hoàng. Trạng thái gia trì chỉ duy trì trong thời gian ngắn.","thuocTinh":"Ánh trăng","uyLuc":"Gia tăng mạnh thần lực và uy năng của các bảo thuật được thi triển trong ánh trăng.","dacDiem":"Chỉ có thể duy trì trong thời gian ngắn.","congNang":["Tiếp dẫn thánh lực mặt trăng.","Gia trì bảo thuật chân long và thần hoàng."],"nguoiTu":[{"ten":"Chủ thân Nguyệt Thiền","tuChuong":"@c0531","tangDatToi":"Chưa rõ","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0531","loai":"thi triển","importance":"normal","giaiDoan":"Tiếp dẫn thánh lực","text":"Chủ thân Nguyệt Thiền khai thông trăng bạc, thu nhận thần lực và gia trì các bảo thuật công phạt.","anchor":"có thể khai thông trăng bạc, diễn sinh thần lực vô lượng"}]},"capNhatToi":"@c0531","nguon":["@c0531"]},{"id":"bao-thuat-chan-long-cua-chu-than-nguyet-thien","name":"Bảo thuật chân long của chủ thân Nguyệt Thiền","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"Chưa rõ","hePhai":"","soHuu":["Chủ thân Nguyệt Thiền"],"blurb":"Bảo thuật ngưng tụ chân long khổng lồ để công phạt.","detail":"Chân long được ngưng tụ trong ánh trăng, mang uy năng chồng chất của bảo thuật và sức mạnh mặt trăng. Khi hợp kích cùng thần hoàng, nó đánh Thạch Hạo bay xa và chảy máu.","thuocTinh":"Chân long và ánh trăng","uyLuc":"Hợp kích cùng thần hoàng đủ sức đánh Thạch Hạo bay và bị thương.","congNang":["Ngưng tụ chân long khổng lồ để công kích.","Chồng sức mạnh mặt trăng lên uy năng bảo thuật."],"nguoiTu":[{"ten":"Chủ thân Nguyệt Thiền","tuChuong":"@c0531","tangDatToi":"Chưa rõ","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0531","loai":"thi triển","importance":"normal","giaiDoan":"Long hoàng hợp kích","text":"Chủ thân Nguyệt Thiền dùng chân long được ánh trăng gia trì để hợp kích Thạch Hạo.","anchor":"Bảo thuật chân long lần này có uy năng chồng chất lên nhau, đi kèm là sức mạnh của mặt trăng"}]},"capNhatToi":"@c0531","nguon":["@c0531"]},{"id":"than-hoang-anh-trang","name":"Thần hoàng ánh trăng","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"Chưa rõ","hePhai":"","soHuu":["Chủ thân Nguyệt Thiền"],"blurb":"Bảo thuật hóa sinh thần hoàng đỏ thẫm pha trắng bạc để công phạt.","detail":"Chủ thân Nguyệt Thiền ngưng tụ thần hoàng trong ánh trăng và cho nó phối hợp với chân long vồ giết Thạch Hạo.","thuocTinh":"Thần hoàng và ánh trăng","congNang":["Ngưng tụ thần hoàng để công kích mục tiêu.","Phối hợp với bảo thuật chân long tạo đòn hợp kích."],"nguoiTu":[{"ten":"Chủ thân Nguyệt Thiền","tuChuong":"@c0531","tangDatToi":"Chưa rõ","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0531","loai":"thi triển","importance":"normal","giaiDoan":"Long hoàng hợp kích","text":"Chủ thân Nguyệt Thiền hóa sinh thần hoàng mang hai màu đỏ thẫm và trắng bạc để cùng chân long tấn công.","anchor":"Cùng lúc đó, một con thần hoàng hiện lên, trong màu đỏ thẫm là vẻ trắng bạc"}]},"capNhatToi":"@c0531","nguon":["@c0531"]},{"id":"kim-lien-dai-dao","name":"Kim liên đại đạo","cn":"","loai":"than-thong","loaiLabel":"Dị tượng","phamCap":"Chưa hoàn thiện","hePhai":"Nguyên thủy chân giải","soHuu":["Thạch Hạo"],"blurb":"Dị tượng kim liên được Thạch Hạo diễn hóa từ phù văn Nguyên thủy chân giải.","detail":"Kim liên xuất hiện khắp hư không rồi được gia trì bằng long khí hoàng cung và thiên long từ ngọc tỷ. Các đóa kim liên mang khí tức đại đạo, đánh tan ánh trăng và đối kháng đòn hợp kích chân long, thần hoàng.","thuocTinh":"Phù văn và đại đạo","uyLuc":"Có thể đánh tan ánh trăng và đối kháng bảo thuật chân long cùng thần hoàng.","dacDiem":"Gần với dị tượng đại đạo nhưng chưa trở thành đạo ngân hoàn chỉnh.","congNang":["Hóa sinh kim liên từ phù văn để công phạt.","Dung nạp long khí hoàng cung và thiên long từ ngọc tỷ."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0531","tangDatToi":"Chưa hoàn thiện","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0531","loai":"xuất hiện","importance":"normal","giaiDoan":"Kim liên công phạt","text":"Thạch Hạo diễn hóa kim liên, dẫn long khí và thiên long vào dị tượng rồi đánh tan ánh trăng.","anchor":"toàn bộ kim liên đều rung động, mang theo khí tức của 'đại đạo', rút rễ bay lên đánh giết về trước"}]},"capNhatToi":"@c0531","nguon":["@c0531"]},{"id":"kiem-y-cua-mot-cay-co","name":"Kiếm ý của một cây cỏ","cn":"","loai":"kiem-quyet","loaiLabel":"Kiếm thuật","phamCap":"Chưa rõ","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Kiếm ý sắc bén được Thạch Hạo phối hợp với biển lôi điện để công kích.","detail":"Kiếm khí xuyên thủng cánh tay và chém thương bả vai chủ thân Nguyệt Thiền, thể hiện sức xuyên phá đủ sức cắt rời hư không.","thuocTinh":"Kiếm khí","uyLuc":"Xuyên thủng cánh tay và chém trọng thương bả vai chủ thân Nguyệt Thiền.","congNang":["Tạo kiếm khí sắc bén xuyên và chém thân thể đối thủ."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0531","tangDatToi":"Chưa rõ","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0531","loai":"thi triển","importance":"normal","giaiDoan":"Kiếm khí xuyên thân","text":"Thạch Hạo phối hợp kiếm ý với lôi điện, xuyên thủng cánh tay và chém thương chủ thân Nguyệt Thiền.","anchor":"một luồng kiếm khí xuyên thủng cánh tay óng ánh như ngó sen của nàng"}]},"capNhatToi":"@c0531","nguon":["@c0531"]},{"id":"tran-phap-thien-thach","name":"Trận pháp thiên thạch","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Sơ sài","hePhai":"","soHuu":["Chủ thân Nguyệt Thiền"],"blurb":"Trận pháp triệu hoán núi đá và thiên thạch để cản đường truy kích.","detail":"Trận pháp chỉ tập trung công kích về một phương và có một số biến hóa. Thứ thân Nguyệt Thiền nhận ra đường đi của trận, giúp Thạch Hạo né thiên thạch và tiếp tục truy đuổi.","thuocTinh":"Thiên thạch","dacDiem":"Chỉ công kích về một phương và có một số biến hóa.","congNang":["Triệu hoán núi đá và thiên thạch xuyên qua hư không để cản đường."],"tabs":{"tienTrinh":[{"chuong":"@c0531","loai":"thi triển","importance":"normal","giaiDoan":"Cản đường truy kích","text":"Chủ thân Nguyệt Thiền dùng trận pháp triệu hoán thiên thạch nhằm ngăn Thạch Hạo truy đuổi.","anchor":"đây là trận pháp sơ sài, có thể triệu hoán các ngọn núi tảng đá, gào thét qua hư không"}]},"capNhatToi":"@c0531","nguon":["@c0531"]},{"id":"uy-luc-chi-ton-cot","name":"Uy lực Chí tôn cốt","cn":"","loai":"than-thong","loaiLabel":"Thần thông thiên phú","phamCap":"Chưa rõ","hePhai":"Chí tôn cốt","soHuu":["Thạch Hạo"],"blurb":"Sức mạnh thiên phú bộc phát từ Chí tôn cốt trong ngực Thạch Hạo.","detail":"Khi được kích hoạt, Chí tôn cốt làm thiên địa bạo động, phát ra tiếng tụng kinh và phù văn vô lượng. Bóng người trên khối cốt còn có thể hóa lớn, mang thần uy Chí tôn đánh tới.","thuocTinh":"Chí tôn và phù văn","uyLuc":"Làm thiên địa bạo động và tạo bóng người mang thần uy Chí tôn công kích.","congNang":["Bộc phát phù văn vô lượng để trấn áp.","Tạo bóng người mang thần uy Chí tôn phát động công kích."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0531","tangDatToi":"Chưa rõ","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0531","loai":"thi triển","importance":"normal","giaiDoan":"Bộc phát thần uy","text":"Thạch Hạo kích hoạt Chí tôn cốt để trấn áp chủ thân Nguyệt Thiền và dùng bóng người trên khối cốt phản kích.","anchor":"uy lực của Chí tôn cốt làn này vượt quá tưởng tượng, còn có tiếng tụng kinh vô cùng lớn truyền ra"}]},"capNhatToi":"@c0531","nguon":["@c0531"]},{"id":"tam-toa-dai-tran-cap-than","name":"Tám tòa đại trận cấp Thần","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Cấp Thần","hePhai":"","soHuu":["Chủ thân Nguyệt Thiền"],"blurb":"Sát trận gồm tám tầng được chủ thân Nguyệt Thiền bố trí quanh chiến trường.","detail":"Các trận kỳ được giấu trong hư không và thiên thạch. Khi kích hoạt, tám tầng đại trận bùng phát khí tức cấp Thần và đánh tan bóng người giả của Thạch Hạo ở trung tâm.","thuocTinh":"Sát trận","uyLuc":"Bùng phát sức mạnh cấp Thần và đánh nát bóng người ở trung tâm trận địa.","dacDiem":"Gồm tám tòa trận pháp với nhiều đại pháp kỳ lẫn trong thiên thạch.","congNang":["Phong tỏa chiến trường bằng tám tầng trận pháp.","Bùng phát lực sát thương cấp Thần tại trung tâm trận địa."],"tabs":{"tienTrinh":[{"chuong":"@c0531","loai":"xuất hiện","importance":"normal","giaiDoan":"Kích hoạt sát trận","text":"Chủ thân Nguyệt Thiền kích hoạt tám tầng đại trận, dùng sức mạnh cấp Thần đánh tan thế thân của Thạch Hạo.","anchor":"chỉ trong chớp mắt đã kích hoạt trận pháp này, tiếng ầm vang lên, khí tức cấp Thần bùng phát"}]},"capNhatToi":"@c0531","nguon":["@c0531"]},{"id":"suc-manh-luan-hoi","name":"Sức mạnh Luân hồi","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Chưa rõ","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Sức mạnh Luân hồi được Thạch Hạo dùng trong cuộc phục kích chủ thân Nguyệt Thiền.","detail":"Sức mạnh này xuất hiện cùng vô số phù văn khi khối thiên thạch che giấu chân thân Thạch Hạo nổ tung, mở màn cho đòn phản kích bằng Chí tôn cốt.","thuocTinh":"Luân hồi","congNang":["Phối hợp phù văn và đòn phục kích nhằm vào đối thủ."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0531","tangDatToi":"Thi triển","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0531","loai":"thi triển","importance":"normal","giaiDoan":"Phá thạch phục kích","text":"Thạch Hạo để sức mạnh Luân hồi tràn ra cùng phù văn khi phá thiên thạch xuất hiện.","anchor":"một khối thiên thạch nổ tung, vô số phù văn lao ra kèm theo đó là sức mạnh Luân hồi"}]},"capNhatToi":"@c0531","nguon":["@c0531"]},{"id":"phuong-phi-cuu-thien","name":"Phượng Phi Cửu Thiên","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Thức thứ nhất của bảo thuật Thần Hoàng","hePhai":"Bổ Thiên giáo","soHuu":["Thứ thân Nguyệt Thiền","Thạch Hạo"],"blurb":"Phượng Phi Cửu Thiên là biến hóa thức thứ nhất trong bảo thuật Thần Hoàng, do thứ thân Nguyệt Thiền truyền cho Thạch Hạo bằng kinh văn viết qua phù bút. Khi thi triển, phù văn đỏ rực hóa thành hình ảnh phượng hoàng giương cánh phi thiên, chỉ một phần biến hóa cũng đã có uy lực cực mạnh và đủ sức làm kinh diễm thế gian.","detail":"Tại thời điểm truyền pháp, thứ thân Nguyệt Thiền dùng phù bút viết kinh văn Phượng Phi Cửu Thiên cho Thạch Hạo, sau đó hắn bắt đầu tiếp nhận và tu tập @c0533. Đây là biến hóa thức thứ nhất thuộc bảo thuật Thần Hoàng; khi kinh văn tiến vào mắt người tu, phù văn biểu hiện thành hình ảnh phượng hoàng đỏ rực giương cánh bay lên trời. Dù mới chỉ là một phần của bảo thuật Thần Hoàng, biến hóa này đã thể hiện uy lực cực mạnh.","thuocTinh":"Thần Hoàng","nguonGoc":"Do thứ thân Nguyệt Thiền truyền cho Thạch Hạo.","uyLuc":"Một phần biến hóa đã có uy lực cực mạnh và đủ sức làm kinh diễm thế gian.","dacDiem":"Biểu hiện thành hình ảnh phượng hoàng đỏ rực giương cánh phi thiên.","chieuTieuBieu":["Phượng Phi Cửu Thiên"],"nguoiTu":[{"ten":"Thứ thân Nguyệt Thiền","tuChuong":"@c0533","tangDatToi":"Nắm giữ và truyền dạy thức thứ nhất","trangThai":"dang-tu"},{"ten":"Thạch Hạo","tuChuong":"@c0533","tangDatToi":"Bắt đầu tu hành thức thứ nhất","trangThai":"dang-tu"}],"congNang":["Thi triển biến hóa phượng hoàng phi thiên bằng phù văn đỏ rực."],"trangThai":"Đang được tu hành","capNhatToi":"@c0533","tabs":{"tienTrinh":[{"chuong":"@c0533","loai":"xuất hiện","importance":"major","giaiDoan":"Truyền thức thứ nhất","text":"Thứ thân Nguyệt Thiền dùng phù bút viết kinh văn Phượng Phi Cửu Thiên truyền cho Thạch Hạo, sau đó hắn bắt đầu chuyên tâm tu hành.","anchor":"khi phù văn rơi vào trong mắt nó thì tựa như có một con phượng hoàng màu đỏ rực giương cánh vọt lên tận trời cao"}]},"nguon":["@c0533"]},{"id":"kiem-tran-do-cua-tieu-hong","name":"Kiếm trận đỏ của tiểu Hồng","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Không rõ","hePhai":"Bảo thuật hỏa hệ","soHuu":["Con chim đỏ nhỏ"],"blurb":"Kiếm trận do Con chim đỏ nhỏ điều động hàng nghìn thần kiếm đỏ kết thành.","detail":"Các thần kiếm đỏ hóa thành ký hiệu và liên kết thành kiếm trận, vừa giam hãm vừa công kích Bóng Lông bằng khí thế giết chóc.","thuocTinh":"Hỏa","uyLuc":"Có thể nhốt Bóng Lông trong một kiếm trận kết từ hàng nghìn thần kiếm đỏ.","dacDiem":"Thần kiếm đỏ hóa thành ký hiệu rồi liên kết thành trận.","chieuTieuBieu":["Kiếm trận tuyệt thế"],"congNang":["Giam hãm và công kích đối thủ bằng vô số thần kiếm đỏ."],"nguoiTu":[{"ten":"Con chim đỏ nhỏ","tuChuong":"@c0535","tangDatToi":"Có thể thi triển kiếm trận hoàn chỉnh","trangThai":"đang tu luyện"}],"tabs":{"tienTrinh":[{"chuong":"@c0535","loai":"thi triển","importance":"normal","giaiDoan":"Kiếm trận hoàn chỉnh","text":"Con chim đỏ nhỏ kết hàng nghìn thần kiếm đỏ thành trận để nhốt và công kích Bóng Lông.","anchor":"tất cả tạo thành một kiếm trận tuyệt thế nhốt Bóng Lông ở bên trong"}]},"capNhatToi":"@c0535","nguon":["@c0535"]},{"id":"kinh-van-cam-ky-trong-son-bao","name":"Kinh văn cấm kỵ trong sơn bảo","cn":"","loai":"bi-thuat","loaiLabel":"Kinh văn cấm kỵ","phamCap":"Không rõ","hePhai":"Không rõ","soHuu":[],"blurb":"Kinh văn cấm kỵ được ghi trong hộp thiên cốt của sơn bảo, chuyên vận chuyển và tổ hợp các loại thần thông. Pháp môn này có thể khiến nhiều bảo thuật quy nhất, được đánh giá mang uy lực cái thế.","detail":"Đây là pháp môn cấm kỵ lưu trong hộp thiên cốt của sơn bảo. Bóng Lông tiết lộ kinh văn có khả năng tổ hợp nhiều loại thần thông và quy nhất các bảo thuật, qua đó thể hiện vai trò liên kết, vận chuyển những năng lực khác nhau trong cùng một hệ thống vận dụng. @c0535","nguonGoc":"Được ghi trong hộp thiên cốt của sơn bảo.","uyLuc":"Kinh văn được xác nhận có uy lực cái thế và khả năng quy nhất nhiều bảo thuật.","dacDiem":"Chuyên vận chuyển, tổ hợp các loại thần thông.","congNang":["Tổ hợp nhiều loại thần thông với nhau. @c0535","Khiến nhiều bảo thuật quy nhất. @c0535"],"tabs":{"tienTrinh":[{"chuong":"@c0535","loai":"hé lộ tầng-chiêu","importance":"major","giaiDoan":"Hé lộ công dụng cốt lõi","text":"Bóng Lông tiết lộ kinh văn trong sơn bảo có thể tổ hợp nhiều thần thông và khiến các bảo thuật quy nhất.","anchor":"nếu như học được thì có thể tổ hợp các loại thần thông lại với nhau"}]},"capNhatToi":"@c0535","nguon":["@c0535"]},{"id":"phap-mon-chim-than","name":"Pháp môn chim thần","cn":"","loai":"cong-phap","loaiLabel":"Bảo thuật","phamCap":"Không rõ","hePhai":"Chim thần","soHuu":["Tử Vân","Đại Bằng","Tiểu Thanh"],"blurb":"Pháp môn chim thần được Thạch Hạo truyền cho ba con chim tại Thạch thôn để giúp chúng tiếp tục tăng cường thực lực.","detail":"Thạch Hạo thực hiện lời hứa bằng cách truyền pháp môn này cho Tử Vân, Đại Bằng và Tiểu Thanh.","nguoiTu":[{"ten":"Tử Vân","tuChuong":"@c0537","tangDatToi":"Bắt đầu tiếp nhận","trangThai":"tu-luyen"},{"ten":"Đại Bằng","tuChuong":"@c0537","tangDatToi":"Bắt đầu tiếp nhận","trangThai":"tu-luyen"},{"ten":"Tiểu Thanh","tuChuong":"@c0537","tangDatToi":"Bắt đầu tiếp nhận","trangThai":"tu-luyen"}],"tabs":{"tienTrinh":[{"chuong":"@c0537","loai":"xuất hiện","importance":"normal","giaiDoan":"Được truyền dạy","text":"Thạch Hạo truyền pháp môn chim thần cho Tử Vân, Đại Bằng và Tiểu Thanh.","anchor":"truyền pháp môn chim thần cho đám Tử Vân, Đại Bằng, Tiểu Thanh"}]},"capNhatToi":"@c0537","nguon":["@c0537"]},{"id":"te-dan-phong-ho-va-truyen-tong-thach-thon","name":"Tế đàn phòng hộ và truyền tống Thạch thôn","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Thần trận nâng cao","hePhai":"Liễu Thần","soHuu":["Thạch thôn"],"blurb":"Tế đàn do Liễu Thần hoàn thành tại Thạch thôn trước khi rời đi, đồng thời đảm nhiệm chức năng phòng hộ và truyền tống cỡ lớn. Công trình có thể bảo vệ Thạch thôn và đưa người tới địa điểm đã xác định tọa độ.","detail":"Do Liễu Thần tạo dựng tại Thạch thôn, đây là bản nâng cao của thần trận cũ, tích hợp khả năng phòng hộ và truyền tống trong cùng một tế đàn. Liễu Thần đã hoàn thành công trình trước khi rời đi; việc vận hành đòi hỏi điều kiện khống chế nghiêm ngặt. @c0537","thuocTinh":"Phòng hộ và không gian","nguonGoc":"Do Liễu Thần tạo dựng tại Thạch thôn.","yeuCau":"Phải xác định tọa độ và khống chế nghiêm ngặt.","congNang":["Bảo vệ Thạch thôn. @c0537","Thực hiện truyền tống cỡ lớn tới địa điểm đã xác định tọa độ. @c0537"],"dacDiem":"Tích hợp hai chức năng phòng hộ và truyền tống trong cùng một tế đàn.","tabs":{"tienTrinh":[{"chuong":"@c0537","loai":"xuất hiện","importance":"major","giaiDoan":"Hoàn thành","text":"Liễu Thần hoàn thành tế đàn phòng hộ kiêm truyền tống cho Thạch thôn trước khi rời đi.","anchor":"Tế đàn này là một trận pháp, có thể bảo vệ Thạch thôn, cũng chính là một truyền tống trận cỡ lớn"}]},"capNhatToi":"@c0537","nguon":["@c0537"]},{"id":"than-hoa-van-ngan","name":"Thân hóa vạn ngàn","cn":"","loai":"than-thong","loaiLabel":"Thần thông Chu Yếm","phamCap":"Không rõ","hePhai":"Tộc Chu Yếm","soHuu":["Bóng Lông"],"blurb":"Thần thông phân hóa ra vô số Thần viên để đồng loạt vây đánh đối thủ.","detail":"Bóng Lông thi triển thần thông tạo ra vô số Thần viên phủ kín thiên địa. Trùng đồng của Thạch Hạo vẫn nhìn xuyên hư ảo và tìm được chân thân.","thuocTinh":"Phân thân","congNang":["Phân hóa vô số Thần viên để bao vây và công kích đối thủ."],"nguoiTu":[{"ten":"Bóng Lông","tuChuong":"@c0537","tangDatToi":"Có thể thi triển","trangThai":"đang dùng"}],"tabs":{"tienTrinh":[{"chuong":"@c0537","loai":"thi triển","importance":"normal","giaiDoan":"Dùng trong giao đấu","text":"Bóng Lông tạo ra vô số Thần viên để vây đánh Thạch Hạo nhưng bị Trùng đồng nhìn ra chân thân.","anchor":"từ trong cơ thể của nó tao ra từng con Thần viên, chỉ trong nháy mắt đã chật ních cả thiên địa"}]},"capNhatToi":"@c0537","nguon":["@c0537"]},{"id":"duong-khi-loi-dinh-cua-lieu-than","name":"Dương khí lôi đình của Liễu Thần","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"Liễu Thần","soHuu":["Liễu Thần"],"blurb":"Thần thông đưa sinh mệnh lực, dương khí và lôi đình vào cành liễu vàng để khắc chế âm linh.","detail":"Liễu Thần khiến cành liễu chuyển thành màu vàng rồi bùng phát sinh mệnh lực, dương khí và lôi đình. Sức mạnh này tịnh hóa những anh linh vượt giới chưa kịp rút khỏi Hoang vực.","thuocTinh":"Dương khí, sinh mệnh lực và lôi đình","uyLuc":"Có thể tịnh hóa anh linh vượt giới và đánh tan lực lượng âm linh của Minh thổ.","dacDiem":"Cành liễu chuyển sang màu vàng và phát ra ánh sáng chói mắt khi thi triển.","congNang":["Khắc chế và tịnh hóa anh linh mang âm khí."],"nguoiTu":[{"ten":"Liễu Thần","tuChuong":"@c0538","tangDatToi":"","trangThai":"đang sử dụng"}],"trangThai":"đang lưu truyền","capNhatToi":"@c0538","tabs":{"tienTrinh":[{"chuong":"@c0538","loai":"thi triển","importance":"normal","giaiDoan":"Tịnh hóa anh linh","text":"Liễu Thần dùng cành liễu vàng mang dương khí và lôi đình để tịnh hóa lực lượng anh linh vượt giới của Minh thổ.","anchor":"còn có cả lực lôi đình, bùng phát ra tia sáng cực chói mắt, tịnh hóa toàn bộ"}]},"nguon":["@c0538"]},{"id":"nguyen-thuy-chan-giai-thien-than-dan","name":"Nguyên thủy chân giải — thiên Thần dẫn","cn":"","loai":"cong-phap","loaiLabel":"Chân giải","phamCap":"","hePhai":"Nguyên thủy chân giải","soHuu":["Thạch Hạo"],"blurb":"Thiên Thần dẫn là một thiên thuộc Nguyên thủy chân giải, trình bày chân nghĩa tương ứng của bộ chân giải này. Phần hiện có chưa hoàn chỉnh do còn thiếu Vạn linh đồ đã vỡ trên Thiên cốt. (+) Phần chân giải cung cấp cốt văn để Thạch Hạo dựng Vạn Linh đồ trong huyết nhục. [CAN-SOAT-GOP]","detail":"Thiên Thần dẫn thuộc Nguyên thủy chân giải. Theo lời Liễu Thần, phần Thạch Hạo nắm giữ vẫn còn thiếu Vạn linh đồ đã vỡ trên Thiên cốt nên chân nghĩa chưa được bổ toàn; người đạt cấp giáo chủ có thể suy diễn chân nghĩa từ phần còn lại, nhưng cảnh giới của Thạch Hạo lúc ấy chưa đủ để thực hiện.","nguonGoc":"Nguyên thủy chân giải","yeuCau":"Cần Vạn linh đồ hoặc cảnh giới đủ cao để suy diễn phần chân nghĩa còn thiếu.","dacDiem":"Phần hiện có chưa hoàn chỉnh vì thiếu Vạn linh đồ đã vỡ trên Thiên cốt. @c0538","congNang":["Trình bày chân nghĩa thuộc thiên Thần dẫn của Nguyên thủy chân giải.","Người đạt cấp giáo chủ có thể suy diễn chân nghĩa từ phần còn lại dù thiếu Vạn linh đồ; Thạch Hạo lúc ấy chưa đạt cảnh giới cần thiết."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0538","tangDatToi":"Chưa lĩnh hội trọn vẹn","trangThai":"đang tu"}],"trangThai":"không hoàn chỉnh","capNhatToi":"@c0538","tabs":{"tienTrinh":[{"chuong":"@c0538","loai":"hé lộ tầng-chiêu","importance":"major","giaiDoan":"Hé lộ phần thiếu","text":"Liễu Thần cho biết thiên Thần dẫn còn thiếu Vạn linh đồ đã vỡ trên Thiên cốt.","anchor":"Thiên Thần dẫn của Nguyên thủy chân giải, ngoại trừ khối mà ngươi đoạt được thì còn có một bức Vạn linh đồ"}]},"nguon":["@c0538","@c0688"]},{"id":"tran-phap-bao-ve-day-leo-ho-lo","name":"Trận pháp bảo vệ dây leo hồ lô","cn":"","loai":"bi-thuat","loaiLabel":"Trận pháp","phamCap":"","hePhai":"Liễu Thần","soHuu":["Liễu Thần"],"blurb":"Trận pháp do Liễu Thần bố trí quanh dây leo hồ lô mang truyền thừa Bổ Thiên các.","detail":"Sau khi tìm được dây leo hồ lô tại di chỉ Bổ Thiên các, Liễu Thần bố trí một trận pháp có tia khí hỗn độn lượn lờ để bảo vệ hạt giống truyền thừa.","nguonGoc":"Do Liễu Thần bố trí tại di chỉ Bổ Thiên các.","thuocTinh":"Có khí hỗn độn lượn lờ","congNang":["Bảo vệ dây leo hồ lô mang truyền thừa Bổ Thiên các."],"nguoiTu":[{"ten":"Liễu Thần","tuChuong":"@c0538","tangDatToi":"","trangThai":"người bố trí"}],"trangThai":"đang vận hành","capNhatToi":"@c0538","tabs":{"tienTrinh":[{"chuong":"@c0538","loai":"xuất hiện","importance":"normal","giaiDoan":"Bảo vệ truyền thừa","text":"Liễu Thần bố trí trận pháp mang một tia khí hỗn độn quanh dây leo hồ lô.","anchor":"Một trận pháp được bố trí, một tia khí hỗn độn lượn lờ"}]},"nguon":["@c0538"]},{"id":"mot-tram-le-tam-canh-hoang-kim","name":"Một trăm lẻ tám cành hoàng kim","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Không rõ","hePhai":"","soHuu":["Liễu Thần"],"blurb":"Một trăm lẻ tám cành hoàng kim là đòn toàn lực do Liễu Thần thi triển, biến các cành cây thành những sợi xích thần trật tự để xuyên phá mục tiêu. Đòn đánh đã phá hủy Bảo luân Minh giới, Minh thổ và thân thể bất hủ của Hỗn độn thi, qua đó tiêu diệt một bá chủ cấp giáo chủ của thượng giới.","detail":"Trên người Liễu Thần lao ra một trăm lẻ tám cành cây hoàng kim, mỗi cành tựa như một sợi xích thần trật tự. Chúng xuyên thủng Bảo luân Minh giới tạo thành nhiều lỗ hổng, đánh nứt rồi phá nổ mảnh Minh thổ, sau đó xuyên qua thân thể bất hủ của Hỗn độn thi và khiến đối phương nổ tung. Với một đòn toàn lực này, Liễu Thần đã tiêu diệt một bá chủ cấp giáo chủ của thượng giới. @c0539","congNang":["Xuyên thủng pháp khí Bảo luân Minh giới và phá nát Minh thổ. @c0539","Xuyên qua, phá hủy thân thể bất hủ của Hỗn độn thi và khiến đối phương nổ tung. @c0539"],"nguoiTu":[{"ten":"Liễu Thần","tuChuong":"@c0539","tangDatToi":"","trangThai":"thi triển"}],"tabs":{"tienTrinh":[{"chuong":"@c0539","loai":"thi triển","importance":"major","giaiDoan":"Thi triển lần đầu","text":"Liễu Thần phóng một trăm lẻ tám cành hoàng kim xuyên thủng Bảo luân Minh giới, phá nát Minh thổ và tiêu diệt Hỗn độn thi chỉ bằng một đòn toàn lực.","anchor":"chỉ trong nháy mắt trên người nó lao ra một trăm lẻ tám cành cây"}]},"nguon":["@c0539"],"uyLuc":"Một đòn toàn lực đã phá hủy Bảo luân Minh giới, Minh thổ và thân thể bất hủ của Hỗn độn thi, tiêu diệt một bá chủ cấp giáo chủ của thượng giới. @c0539","dacDiem":"Gồm một trăm lẻ tám cành cây hoàng kim phóng ra từ người Liễu Thần, mỗi cành tựa như một sợi xích thần trật tự."},{"id":"ngu-hanh-than","name":"Ngũ hành thân","cn":"五行身","loai":"cong-phap","loaiLabel":"Công pháp","phamCap":"Không rõ","hePhai":"Ngũ hành","soHuu":["Bất lão Thiên tôn"],"blurb":"Ngũ hành thân là pháp môn của Bất lão Thiên tôn, cho phép năm chân thân tương ứng Ngũ hành đồng thời tồn tại. Cả năm đều là chân thân chứ không phải hóa thân và có thể phối hợp hợp kích.","detail":"Bất lão Thiên tôn từng đồng thời hiện đủ năm chân thân Ngũ hành để vây công Liễu Thần; Tiểu Tháp xác nhận tất cả đều là chân thân. Căn nguyên của trạng thái này chưa được xác nhận: có thể là năm người cùng tồn tại, hoặc một người nắm Ngũ hành nên có năm mệnh. @c0539","congNang":["Cho phép năm chân thân tương ứng Ngũ hành đồng thời tồn tại, mỗi thân đều là chân thân chứ không phải hóa thân. @c0539","Năm chân thân có thể phối hợp hợp kích. @c0539"],"nguoiTu":[{"ten":"Bất lão Thiên tôn","tuChuong":"@c0539","tangDatToi":"","trangThai":"năm chân thân"}],"tabs":{"tienTrinh":[{"chuong":"@c0539","loai":"he lo tang-chieu","importance":"major","giaiDoan":"Hé lộ bí mật năm chân thân","text":"Bất lão Thiên tôn đồng thời hiện đủ năm chân thân Ngũ hành vây công Liễu Thần, Tiểu Tháp xác nhận tất cả đều là chân thân.","anchor":"tất cả đều là chân thân, có người nói Bất lão Thiên tôn có tổng cộng năm người"}]},"nguon":["@c0539"],"uyLuc":"Bất lão Thiên tôn từng đồng thời hiện đủ năm chân thân Ngũ hành để vây công Liễu Thần. @c0539","dacDiem":"Năm thân cùng tồn tại đều là chân thân, lần lượt tương ứng với Ngũ hành; cơ chế hình thành năm chân thân chưa được xác nhận."},{"id":"ba-ngan-gioi-than-thong","name":"Ba ngàn giới","cn":"三千界","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Không rõ","hePhai":"","soHuu":["Liễu Thần"],"blurb":"Thần thông do Liễu Thần thi triển, mi tâm phát sáng diễn hóa ba ngàn thế giới như các chùm sáng đang cháy để bao phủ mục tiêu.","detail":"Mi tâm Liễu Thần phát sáng, xung quanh lập tức hiện lên ba ngàn giới, mỗi một giới tựa như một chùm sáng óng ánh đang cháy, dùng để bao phủ gốc cây khổng lồ của một chân thân Ngũ hành.","congNang":["Diễn hóa ba ngàn thế giới ánh sáng bao phủ mục tiêu"],"nguoiTu":[{"ten":"Liễu Thần","tuChuong":"@c0539","tangDatToi":"","trangThai":"thi triển"}],"tabs":{"tienTrinh":[{"chuong":"@c0539","loai":"thi triển","importance":"normal","giaiDoan":"Thi triển lần đầu","text":"Liễu Thần thi triển ba ngàn giới, diễn hóa các chùm sáng bao phủ gốc cây khổng lồ của một chân thân Ngũ hành.","anchor":"xung quanh lập tức hiện lên ba ngàn giới, mỗi một giới tựa như một chùm sáng óng ánh"}]},"nguon":["@c0539"]},{"id":"phap-an-chi-troi-chi-dat","name":"Pháp ấn chỉ trời chỉ đất","cn":"","aliases":["Pháp ấn hợp nhất thiên địa"],"loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Không rõ","hePhai":"","soHuu":["Liễu Thần"],"blurb":"Pháp ấn chỉ trời chỉ đất do Liễu Thần kết thành từ tư thế một tay chỉ trời, một tay chỉ đất, mang khí đại đạo vô thượng. Pháp ấn từng được dùng để tiêu diệt cả thân thể lẫn nguyên thần của đạo nhân Âm Dương.","detail":"Liễu Thần thi triển pháp ấn bằng cách kết hợp thế chỉ trời và chỉ đất, tạo nên một pháp ấn tự nhiên mang khí đại đạo vô thượng. Pháp ấn đánh tan thân thể đạo nhân Âm Dương, sau đó tiếp tục tiêu diệt nguyên thần được hai khí âm dương bao quanh, khiến vị bá chủ này hình thần đều diệt. @c0540","uyLuc":"Có thể khiến một đời bá chủ như đạo nhân Âm Dương hình thần đều diệt. @c0540","dacDiem":"Pháp ấn tự nhiên được kết hợp từ thế một tay chỉ trời, một tay chỉ đất và mang khí đại đạo vô thượng. @c0540","chieuTieuBieu":["Pháp ấn chỉ trời chỉ đất"],"nguoiTu":[{"ten":"Liễu Thần","tuChuong":"@c0540","tangDatToi":"Không rõ","trangThai":"đang sử dụng"}],"congNang":["Tiêu diệt cả thân thể lẫn nguyên thần của đối thủ. @c0540"],"trangThai":"Đang được Liễu Thần sử dụng","capNhatToi":"@c0540","tabs":{"tienTrinh":[{"chuong":"@c0540","loai":"thi triển","importance":"major","giaiDoan":"Diệt bá chủ","text":"Liễu Thần kết pháp ấn mang khí đại đạo vô thượng và dùng nó tiêu diệt cả thân thể lẫn nguyên thần của đạo nhân Âm dương.","anchor":"Liễu Thần một tay chỉ trời cao, một tay chỉ mặt đất, pháp ấn tự nhiên, từ từ kết hợp lại"}]},"nguon":["@c0540"]},{"id":"van-linh-hoa-vet-tich","name":"Vạn linh hóa vết tích","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Không rõ","hePhai":"","soHuu":["Tiểu Tháp"],"blurb":"Thần thông khiến hình ảnh hàng vạn sinh linh trên thân Tiểu Tháp hóa thành vết tích để phát động công kích.","detail":"Khi đối kháng người cầm Luân Hồi Bàn, Tiểu Tháp hiển hóa các vết tích Thao Thiết, Kim Ô, Tỳ Hưu và nhiều sinh linh khác cùng vồ giết đối thủ.","thuocTinh":"Hiển hóa vạn linh","uyLuc":"Huy động hàng vạn vết tích sinh linh cùng công kích.","dacDiem":"Các sinh linh hiện trên thân tháp rồi hóa thành vết tích.","nguoiTu":[{"ten":"Tiểu Tháp","tuChuong":"@c0540","tangDatToi":"Không rõ","trangThai":"đang sử dụng"}],"congNang":["Hiển hóa vết tích hàng vạn sinh linh để vồ giết mục tiêu."],"trangThai":"Đang được Tiểu Tháp sử dụng","capNhatToi":"@c0540","tabs":{"tienTrinh":[{"chuong":"@c0540","loai":"thi triển","importance":"normal","giaiDoan":"Đối kháng Luân Hồi Bàn","text":"Tiểu Tháp hiển hóa hàng vạn sinh linh trên thân tháp thành những vết tích cùng lao vào người cầm Luân Hồi Bàn.","anchor":"trên thân tháp hiện lên hàng vạn sinh linh, như Thao thiết, Kim ô, Tỳ hưu.... tất cả hóa thành các vết tích vồ giết"}]},"nguon":["@c0540"]},{"id":"sat-tran-thu-tu","name":"Sát trận thứ tư","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Không rõ","hePhai":"Thượng giới","soHuu":[],"blurb":"Sát trận do nhiều bá chủ thượng giới liên thủ điều khiển để vây giết Liễu Thần và Tiểu Tháp.","detail":"Trận pháp phát ra khí hỗn độn cùng vô số luồng sáng giết chóc. Các công kích của trận bị cánh cửa nguyên thủy thu nhận khi vây công Liễu Thần và Tiểu Tháp.","uyLuc":"Có khả năng đẩy Liễu Thần và Tiểu Tháp vào đại nạn khi được nhiều bá chủ cùng điều khiển.","dacDiem":"Phát ra khí hỗn độn và các luồng sáng giết chóc.","congNang":["Liên thủ vây giết những cường giả cấp bá chủ."],"trangThai":"Được các bá chủ thượng giới sử dụng","capNhatToi":"@c0541","tabs":{"tienTrinh":[{"chuong":"@c0541","loai":"thi triển","importance":"normal","giaiDoan":"Vây công Liễu Thần","text":"Nhiều bá chủ thượng giới vận hành sát trận thứ tư để vây giết Liễu Thần và Tiểu Tháp, nhưng các luồng sáng giết chóc bị cánh cửa nguyên thủy thu nhận.","anchor":"Sát trận thứ tư danh bất hư truyền, vang dội cổ kim"}]},"nguon":["@c0541"]},{"id":"sat-tran-la-lieu","name":"Sát trận lá liễu","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Không rõ","hePhai":"Liễu Thần","soHuu":["Liễu Thần"],"blurb":"Trận pháp do Liễu Thần bố trí bằng những chiếc lá xanh hóa thành trận kỳ.","detail":"Những chiếc lá liễu hóa thành trận kỳ, tạo ra phù văn như xiềng xích để giam giữ và khóa chặt một bá chủ.","dacDiem":"Lá xanh hóa thành trận kỳ và tỏa ra bảo quang.","congNang":["Giam giữ và khóa chặt mục tiêu bằng phù văn trận pháp."],"nguoiTu":[{"ten":"Liễu Thần","tuChuong":"@c0541","tangDatToi":"Có thể bắt giữ một bá chủ","trangThai":"Đang sử dụng"}],"trangThai":"Đã được kích hoạt","capNhatToi":"@c0541","tabs":{"tienTrinh":[{"chuong":"@c0541","loai":"thi triển","importance":"normal","giaiDoan":"Bắt giữ bá chủ","text":"Liễu Thần kích hoạt những chiếc lá hóa thành trận kỳ, dùng phù văn giam giữ một bá chủ trước khi ném người này vào cánh cửa nguyên thủy.","anchor":"từng chiếc lá xuất hiện, không ngừng lơ lửng, ánh xanh chiếu rọi, tất cả đều tỏa ra bảo quang, hóa thành trận kỳ."}]},"nguon":["@c0541"]},{"id":"niet-ban-phap-cua-xich-hoang-cung","name":"Niết bàn pháp của Xích hoàng cung","cn":"","aliases":[],"loai":"cong-phap","loaiLabel":"Công pháp","phamCap":"Không rõ","hePhai":"Xích hoàng cung","soHuu":[],"blurb":"Pháp môn của Xích hoàng cung được Hồng Hoàng giới thiệu với Thạch Hạo. Công pháp này thích hợp cho việc lột xác và hướng người tu tới sự toàn vẹn của đại đạo.","detail":"Hồng Hoàng cho rằng Thạch Hạo đã tu hành nhiều năm trong môi trường pháp tắc không hoàn chỉnh của hạ giới nên cần một lần lột xác khi tiến vào thượng giới. Nàng dùng Niết bàn pháp của Xích hoàng cung làm điều kiện mời nó gia nhập.","thuocTinh":"Niết bàn và lột xác","nguonGoc":"Xích hoàng cung","uyLuc":"Giúp người tu lột xác và hướng tới sự toàn vẹn của đại đạo.","dacDiem":"Được giới thiệu là phù hợp với người đã tu hành lâu năm trong pháp tắc thiếu hụt của hạ giới.","congNang":["Giúp người tu lột xác và làm đại đạo toàn vẹn."],"nguoiTu":[],"trangThai":"Đang được Xích hoàng cung truyền thừa","capNhatToi":"@c0542","tabs":{"tienTrinh":[{"chuong":"@c0542","loai":"xuất hiện","importance":"normal","giaiDoan":"Được giới thiệu","text":"Hồng Hoàng giới thiệu Niết bàn pháp như điều kiện thu hút Thạch Hạo tới Xích hoàng cung.","anchor":"Niết bàn pháp của Xích hoàng cung ta là thích hợp nhất."}]},"nguon":["@c0542"]},{"id":"bach-thu-chan-kinh","name":"Bách thú chân kinh","cn":"","loai":"cong-phap","loaiLabel":"Chân kinh","phamCap":"Không rõ","hePhai":"Thú hải","soHuu":[],"blurb":"Chân kinh do Thủy tổ Thú hải diễn hóa sau một trăm năm nghiên cứu cốt văn của các trùng thú cấp thấp.","detail":"Bách thú chân kinh từng làm chấn động thượng giới, được dùng làm dẫn chứng rằng nghiên cứu sinh linh cấp thấp vẫn có thể mở ra đại đạo.","nguonGoc":"Thủy tổ Thú hải dành một trăm năm nghiên cứu cốt văn của trùng thú cấp thấp rồi diễn hóa thành.","dacDiem":"Cho thấy cốt văn của những sinh linh cấp thấp vẫn có thể trở thành cơ sở diễn hóa đại đạo.","congNang":["Hệ thống hóa kết quả nghiên cứu cốt văn của nhiều loại trùng thú cấp thấp để diễn hóa con đường tu hành."],"capNhatToi":"@c0543","tabs":{"tienTrinh":[{"chuong":"@c0543","loai":"xuất hiện","importance":"normal","giaiDoan":"Được nhắc tại buổi luận đạo","text":"Oánh Oánh kể lại nguồn gốc Bách thú chân kinh để chứng minh giá trị của việc nghiên cứu cốt văn sinh linh cấp thấp.","anchor":"dành cả trăm năm để xem cốt văn của các trùng thú cấp thấp"}]},"nguon":["@c0543"]},{"id":"tu-vuc-cot-hai","name":"Tử vực cốt hải","cn":"","loai":"than-thong","loaiLabel":"Thần thông vực triệu hóa","phamCap":"Không rõ","hePhai":"Minh thổ","soHuu":["Thần phó xương khô có cánh"],"blurb":"Triệu hóa một tử vực chứa biển xương, cốt linh và vong linh thức tỉnh để công kích đối thủ.","detail":"Thần phó Minh thổ triển khai tử vực giữa minh vụ và tử khí. Bên trong vực có nhiều cốt linh cùng vong linh thức tỉnh, tạo thành thế công đối kháng vị Thần của Bất Lão sơn.","thuocTinh":"Minh vụ và tử khí","uyLuc":"Triệu hóa cốt hải cùng nhiều cốt linh để công kích.","dacDiem":"Hình thành một mảnh vực chứa đầy sinh linh xương cốt.","congNang":["Triệu hóa cốt hải, cốt linh và vong linh thức tỉnh để tấn công đối thủ. @c0544"],"nguoiTu":[{"ten":"Thần phó xương khô có cánh","tuChuong":"@c0544","tangDatToi":"Có thể triệu hóa tử vực","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0544","loai":"thi triển","importance":"normal","giaiDoan":"Triệu hóa tử vực","text":"Thần phó Minh thổ triệu hóa biển xương cùng nhiều cốt linh và vong linh để công kích vị Thần của Bất Lão sơn.","anchor":"Đây là một mảnh 'vực' được triệu hóa ra, bên trong có rất nhiều cốt linh"}]},"capNhatToi":"@c0544","nguon":["@c0544"]},{"id":"hoa-vuc-ngu-hanh","name":"Hỏa vực ngũ hành","cn":"","loai":"than-thong","loaiLabel":"Thần thông vực triệu hóa","phamCap":"Không rõ","hePhai":"Bất Lão sơn","soHuu":["Vị Thần mang tinh khí ngũ hành"],"blurb":"Triệu hóa một vùng ánh lửa và dung nham sôi trào để đối kháng, tịnh hóa tử vực.","detail":"Vị Thần của Bất Lão sơn gọi ra hỏa vực ngũ hành khi đối đầu thần phó Minh thổ. Ánh lửa cùng dung nham trong vực tràn tới, tịnh hóa tử khí và biển xương của đối phương.","thuocTinh":"Ngũ hành hỏa","uyLuc":"Có thể tịnh hóa tử vực do thần phó Minh thổ triệu hóa.","dacDiem":"Ánh lửa cuồn cuộn hòa cùng dung nham sôi trào.","congNang":["Tịnh hóa tử vực, tử khí và cốt hải của Minh thổ. @c0544"],"nguoiTu":[{"ten":"Vị Thần mang tinh khí ngũ hành","tuChuong":"@c0544","tangDatToi":"Có thể triệu hóa hỏa vực","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0544","loai":"thi triển","importance":"normal","giaiDoan":"Tịnh hóa tử vực","text":"Vị Thần Bất Lão sơn triệu hóa ánh lửa cùng dung nham để tịnh hóa tử vực của thần phó Minh thổ.","anchor":"ánh lửa cuồn cuộn, dung nham sôi trào tràn về trước tịnh hóa mảnh 'tử vực' kia"}]},"capNhatToi":"@c0544","nguon":["@c0544"]},{"id":"bao-thuat-thien-cot","name":"Bảo thuật thiên cốt","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"Không rõ","hePhai":"Thiên cốt của Thạch Hạo","soHuu":["Thạch Hạo"],"blurb":"Bảo thuật phát động khi Thạch Hạo tế thiên cốt, có thể khiến các mục tiêu nhanh chóng già yếu và suy kiệt.","detail":"Thạch Hạo tế thiên cốt rồi triển khai bảo thuật bao phủ đồng thời ba truyền nhân trẻ tuổi của Minh thổ, Bất Lão sơn và Ma Quỳ viên. Cả ba mất trạng thái thanh xuân, tóc bạc và sức lực suy giảm nhanh chóng.","thuocTinh":"Làm suy thoái trạng thái sinh mệnh","uyLuc":"Đồng thời tác động ba truyền nhân thượng giới và khiến họ nhanh chóng già yếu.","dacDiem":"Được phát động thông qua thiên cốt của Thạch Hạo.","congNang":["Khiến mục tiêu nhanh chóng già yếu, tóc bạc và suy kiệt. @c0544"],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0544","tangDatToi":"Có thể đồng thời tác động ba mục tiêu","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0544","loai":"thi triển","importance":"normal","giaiDoan":"Làm ba truyền nhân già yếu","text":"Thạch Hạo tế thiên cốt và dùng bảo thuật khiến ba truyền nhân trẻ tuổi đồng loạt già yếu, suy nhược.","anchor":"ba người này vẫn sợ hãi không thôi, tự nhiên đều bị bảo thuật quét trúng"}]},"capNhatToi":"@c0544","nguon":["@c0544"]},{"id":"bao-thuat-ma-quy","name":"Bảo thuật Ma quỳ","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật thiên phú","phamCap":"Không rõ","hePhai":"Ma quỳ viên","soHuu":["Cô gái áo đen"],"blurb":"Bảo thuật thiên phú của Ma quỳ nữ, tạo ra một vầng thái dương đen khổng lồ.","detail":"Vầng thái dương đen vừa bao phủ người thi triển vừa tấn công đối thủ. Khi cô gái áo đen dùng bảo thuật này chống Thạch Hạo, nó bị lực Côn bằng phá tan.","thuocTinh":"Hắc ám","uyLuc":"Tạo thái dương đen công kích và hộ thân nhưng bị Bảo thuật Côn bằng của Thạch Hạo phá vỡ.","dacDiem":"Biểu hiện thành một vầng thái dương màu đen cực lớn.","congNang":["Tạo thái dương đen để công kích và hộ thân."],"nguoiTu":[{"ten":"Cô gái áo đen","tuChuong":"@c0545","tangDatToi":"Có thể thi triển","trangThai":"đang tu"}],"tabs":{"tienTrinh":[{"chuong":"@c0545","loai":"thi triển","importance":"normal","giaiDoan":"Thái dương đen","text":"Cô gái áo đen tạo ra thái dương đen để công kích và hộ thân, nhưng bị lực Côn bằng của Thạch Hạo phá tan.","anchor":"Nàng xuất ra bảo thuật, một vầng thái dương màu đen cực lớn hiện ra"}]},"trangThai":"đang lưu truyền","capNhatToi":"@c0545","nguon":["@c0545"]},{"id":"thien-phu-ma-quy","name":"Thiên phú Ma quỳ","cn":"","loai":"than-thong","loaiLabel":"Thần thông chủng tộc","phamCap":"Không rõ","hePhai":"Ma quỳ viên","soHuu":["Cô gái áo đen"],"blurb":"Thiên phú thực vật cho phép Ma quỳ nữ dùng tóc và rễ cây tấn công đối thủ.","detail":"Ma quỳ nữ điều khiển tóc đâm vào đầu đối phương và sinh rễ cây quấn quanh thân thể nhằm hút tinh hoa máu thịt.","thuocTinh":"Thực vật","uyLuc":"Có thể dùng tóc và rễ cây đồng thời vây công, xuyên đâm và hút tinh hoa máu thịt.","dacDiem":"Rễ cây mọc trực tiếp từ thân thể người thi triển.","congNang":["Dùng tóc và rễ cây công kích, trói buộc và hút tinh hoa máu thịt."],"nguoiTu":[{"ten":"Cô gái áo đen","tuChuong":"@c0545","tangDatToi":"Có thể thi triển","trangThai":"đang tu"}],"tabs":{"tienTrinh":[{"chuong":"@c0545","loai":"thi triển","importance":"normal","giaiDoan":"Tóc và rễ cây","text":"Cô gái áo đen dùng tóc cùng rễ cây bao vây Thạch Hạo và tìm cách hút tinh hoa máu thịt của hắn.","anchor":"thân thể sinh ra những rễ cây bao vây lấy thân thể của Thạch Hạo"}]},"trangThai":"đang lưu truyền","capNhatToi":"@c0545","nguon":["@c0545"]},{"id":"thuat-dinh-than-cua-sinh-linh-bat-diet","name":"Thuật định thân của Sinh linh Bất diệt","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Không rõ","hePhai":"Sinh linh Bất diệt","soHuu":["Sinh linh Bất diệt"],"blurb":"Thần thông có thể đồng thời cố định nhiều linh thân mạnh.","detail":"Sinh linh Bất diệt vận dụng sức mạnh thông qua những tiếng hô của Thạch Hạo, khiến bốn linh thân đang vây sát hắn đồng thời bị khóa lại.","congNang":["Cố định đồng thời các linh thân mạnh."],"nguoiTu":[{"ten":"Sinh linh Bất diệt","tuChuong":"@c0546","tangDatToi":"","trangThai":"thi triển"}],"tabs":{"tienTrinh":[{"chuong":"@c0546","loai":"thi triển","importance":"normal","giaiDoan":"Cố định bốn linh thân","text":"Thần thông đồng thời khóa bốn linh thân đang vây sát Thạch Hạo.","anchor":"Bốn linh thân mạnh mẽ kia đều bị ổn định"}]},"capNhatToi":"@c0546","nguon":["@c0546"]},{"id":"than-thong-ban-tay-vang","name":"Thần thông bàn tay vàng","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Không rõ","hePhai":"Sinh linh Bất diệt","soHuu":["Sinh linh Bất diệt"],"blurb":"Bàn tay vàng khổng lồ mang khí tức bất hủ, có thể trấn áp không gian và bắt mục tiêu từ xa.","detail":"Sinh linh Bất diệt dùng bàn tay vàng phá các thủ đoạn đào thoát, ép những chân thân Thần hỏa đã rời hiện trường hiện ra rồi kéo trở lại.","uyLuc":"Có thể bắt lại mục tiêu đã dùng Phá không phù chạy xa vạn dặm.","congNang":["Giam cầm và bắt mục tiêu từ khoảng cách rất xa.","Phá thủ đoạn đào thoát bằng trận đài và Phá không phù."],"nguoiTu":[{"ten":"Sinh linh Bất diệt","tuChuong":"@c0546","tangDatToi":"","trangThai":"thi triển"}],"tabs":{"tienTrinh":[{"chuong":"@c0546","loai":"thi triển","importance":"normal","giaiDoan":"Bắt các chân thân bỏ trốn","text":"Bàn tay vàng trấn áp trời đất và kéo các cường giả Thần hỏa đã phá không bỏ trốn trở lại.","anchor":"Một bàn tay màu vàng, sợ còn lớn hơn cả đám mấy kia rất nhiều"}]},"capNhatToi":"@c0546","nguon":["@c0546"]},{"id":"thon-phe-than-linh","name":"Thôn phệ thần linh","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Không rõ","hePhai":"Sinh linh Bất diệt","soHuu":["Sinh linh Bất diệt"],"blurb":"Thần thông giúp Sinh linh Bất diệt hút và nuốt các cường giả đã nhen nhóm Thần hỏa.","detail":"Xương khô Minh thổ, cường giả Bất Lão sơn, Ma quỳ, Hắc kim tước và nhiều tồn tại cùng cấp bị hút vào miệng Sinh linh Bất diệt rồi biến mất.","congNang":["Hút và nuốt hàng loạt cường giả đã nhen nhóm Thần hỏa."],"nguoiTu":[{"ten":"Sinh linh Bất diệt","tuChuong":"@c0546","tangDatToi":"","trangThai":"thi triển"}],"tabs":{"tienTrinh":[{"chuong":"@c0546","loai":"thi triển","importance":"normal","giaiDoan":"Nuốt các cường giả Thần hỏa","text":"Sinh linh Bất diệt hút hàng loạt cường giả đã nhen nhóm Thần hỏa vào miệng.","anchor":"toàn bộ đều tiến vào trong miệng của hắn"}]},"capNhatToi":"@c0546","nguon":["@c0546"]},{"id":"dai-tran-ho-toc-thac-bat","name":"Đại trận hộ tộc Thác Bạt","cn":"","aliases":[],"loai":"khac","loaiLabel":"Trận pháp","phamCap":"Không rõ","hePhai":"Thác Bạt gia","soHuu":["Thác Bạt gia"],"blurb":"Đại trận bảo vệ sơn môn và cổ địa của Thác Bạt gia.","detail":"Khi sơn môn bị tấn công, đại trận phát sáng và phù văn tăng mạnh để bảo vệ cổ địa, nhưng vẫn bị Thạch Hạo phá vỡ.","thuocTinh":"Phòng hộ","congNang":["Bảo vệ sơn môn và cổ địa Thác Bạt."],"dacDiem":"Phù văn tăng mạnh khi bị công kích.","trangThai":"Bị phá","capNhatToi":"@c0549","tabs":{"tienTrinh":[{"chuong":"@c0549","loai":"thi triển","importance":"normal","giaiDoan":"Bảo vệ cổ địa","text":"Đại trận được kích hoạt để bảo vệ Thác Bạt gia nhưng không ngăn được Thạch Hạo xông vào.","anchor":"Thác Bạt tộc là gia tộc từ thượng cổ, gốc gác tự nhiên thâm hậu, trong lúc này đại trận lấp lánh, phù văn tăng mạnh nhanh chóng bảo vệ nơi đây."}]},"nguon":["@c0549"]},{"id":"dai-tran-tinh-dau","name":"Đại trận Tinh đấu","cn":"","loai":"khac","loaiLabel":"Trận pháp hộ sơn","phamCap":"Không rõ","hePhai":"Thác Bạt tộc","soHuu":["Thác Bạt tộc"],"blurb":"Đại trận Tinh đấu là hộ trận của Thác Bạt tộc, liên kết núi đá với tinh tú và dẫn tinh quang từ chín tầng trời xuống chiến trường. Khi được khởi động để chống lại Thạch Hạo, đại trận biến khu vực bên trong thành biển sao, nhưng cuối cùng bị phá giải do các trận đài đã hao mòn.","detail":"Đại trận Tinh đấu được Thác Bạt tộc sử dụng làm hộ trận, dựa vào các trận đài để liên kết núi đá với tinh tú. Tại lần xuất hiện đã ghi nhận, trận pháp được khởi động nhằm chống Thạch Hạo, dẫn ánh sao từ chín tầng trời và biến khu vực trong trận thành biển sao. Tuy nhiên, các trận đài lâu đời đã hao mòn, nên đại trận bị chiến xa hoàng kim và pháp kiếm thần linh của Thạch quốc công phá, giải thể hoàn toàn. @c0550","thuocTinh":"Tinh quang","congNang":["Liên kết núi đá với tinh tú để hình thành hộ trận của Thác Bạt tộc. @c0550","Dẫn tinh quang từ chín tầng trời xuống chiến trường và biến khu vực trong trận thành biển sao. @c0550"],"dacDiem":"Vận hành thông qua các trận đài liên kết núi đá với tinh tú; các trận đài đã hao mòn theo thời gian và đại trận giải thể khi bị thần khí công phá.","trangThai":"Bị phá hủy","capNhatToi":"@c0550","tabs":{"tienTrinh":[{"chuong":"@c0550","loai":"xuất hiện","importance":"major","giaiDoan":"Hộ trận bị phá","text":"Đại trận Tinh đấu được khởi động để chống Thạch Hạo nhưng các trận đài hao mòn bị phá, khiến núi đá mất liên hệ với tinh tú.","anchor":"Cuối cùng, đại trận giải thể, từng tảng đá lớn nổ tung"}]},"nguon":["@c0550"]},{"id":"than-thong-co-xanh-hoa-kiem","name":"Thần thông cỏ xanh hóa kiếm","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Không rõ","hePhai":"Không rõ","soHuu":["Thạch Hạo"],"blurb":"Thần thông khiến từng cây cỏ xanh hóa thành thần kiếm cắm rễ trong hư không.","detail":"Thạch Hạo dùng kiếm khí phát ra từ những cây cỏ hóa kiếm để tiêu diệt liên tiếp những người Thác Bạt từng tham gia tàn sát Bổ Thiên Các.","thuocTinh":"Kiếm khí","congNang":["Biến cỏ xanh thành thần kiếm cắm rễ trong hư không. @c0550"],"uyLuc":"Kiếm khí giết liên tiếp những người Thác Bạt xông tới.","nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0550","tangDatToi":"","trangThai":"thi triển"}],"capNhatToi":"@c0550","tabs":{"tienTrinh":[{"chuong":"@c0550","loai":"thi triển","importance":"normal","giaiDoan":"Thanh toán hung thủ","text":"Thạch Hạo biến cỏ xanh thành thần kiếm và dùng kiếm khí giết những người Thác Bạt xông tới.","anchor":"từng cây cỏ màu xanh cứ như là thần kiếm cắm rễ trong hư không"}]},"nguon":["@c0550"]},{"id":"thua-phong-thuat","name":"Thừa Phong thuật","cn":"","loai":"than-thong","loaiLabel":"Thân pháp","phamCap":"Không rõ","hePhai":"Tử Phủ sơn","soHuu":["Tam hắc"],"blurb":"Thân pháp tăng tốc độ di chuyển, được Tam hắc học một phần.","detail":"Tam hắc cho biết nó đã học một ít Thừa Phong thuật, nhờ đó có tốc độ di chuyển rất nhanh dù mang thân rùa.","thuocTinh":"Thân pháp tăng tốc","congNang":["Tăng tốc độ di chuyển."],"nguoiTu":[{"ten":"Tam hắc","tuChuong":"@c0551","tangDatToi":"Một ít","trangThai":"Đang tu"}],"tabs":{"tienTrinh":[{"chuong":"@c0551","loai":"xuất hiện","importance":"normal","giaiDoan":"Học một phần","text":"Tam hắc tiết lộ mình đã học một ít Thừa Phong thuật để tăng tốc độ di chuyển.","anchor":"tuy rằng đã học một ít Thừa Phong thuật"}]},"capNhatToi":"@c0551","nguon":["@c0551"]},{"id":"kiem-khi-canh-kim","name":"Kiếm khí canh kim","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Không rõ","hePhai":"Kim đạo","soHuu":["Tôn giả Bạch Hổ"],"blurb":"Thần thông sát phạt của Tôn giả Bạch Hổ, dùng Kim tinh khí hóa thành loạn kiếm.","detail":"Kiếm khí canh kim được phóng ra khi Tôn giả Bạch Hổ mở miệng, có sức uy hiếp Tôn giả bình thường nhưng bị bảo thuật Toan Nghê của Thạch Hạo đánh tan.","thuocTinh":"Canh kim","uyLuc":"Có thể làm trọng thương Tôn giả bình thường.","dacDiem":"Vận chuyển Kim tinh khí thành kiếm khí chuyên chủ sát phạt.","congNang":["Vận chuyển Kim tinh khí để tạo kiếm khí sát phạt."],"nguoiTu":[{"ten":"Tôn giả Bạch Hổ","tuChuong":"@c0554","tangDatToi":"Thi triển trong chiến đấu","trangThai":"Đã thi triển"}],"tabs":{"tienTrinh":[{"chuong":"@c0554","loai":"thi triển","importance":"normal","giaiDoan":"Giao chiến tại lối ra Tây Lăng giới","text":"Tôn giả Bạch Hổ phóng kiếm khí canh kim tập kích Thạch Hạo nhưng bị bảo thuật Toan Nghê đánh tan.","anchor":"lúc nó mở miệng thì kiếm khí canh kim trào ra, chủ sát phạt"}]},"capNhatToi":"@c0554","nguon":["@c0554"]},{"id":"su-tu-hong","name":"Sư tử Hống","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Không rõ","hePhai":"Tộc sư tử","soHuu":["Sư tử già"],"blurb":"Sư tử Hống là thần thông âm ba do Sư tử già thi triển trong cuộc tập kích nhóm Thạch Hạo. Tiếng gầm có thể đánh rơi và phá hủy pháp khí đang công kích. (+) Đại thần thông sóng âm có khả năng trấn áp vạn thú và sát thương sinh linh. [CAN-SOAT-GOP]","detail":"Trong cuộc tập kích nhóm Thạch Hạo, Sư tử già thi triển Sư tử Hống, dùng tiếng gầm đánh rơi các pháp khí do nhóm Tiêu Thiên tung ra, đồng thời khiến một số pháp khí nổ tung. @c0554","uyLuc":"Có thể đồng thời đánh rơi nhiều pháp khí đang công kích và làm một số pháp khí nổ tung.","dacDiem":"Dùng tiếng gầm tạo thành đòn công kích âm ba.","congNang":["Dùng âm ba từ tiếng gầm đánh rơi pháp khí của đối phương và khiến một số pháp khí nổ tung. @c0554"],"nguoiTu":[{"ten":"Sư tử già","tuChuong":"@c0554","tangDatToi":"Thi triển trong chiến đấu","trangThai":"Đã thi triển"}],"tabs":{"tienTrinh":[{"chuong":"@c0554","loai":"thi triển","importance":"normal","giaiDoan":"Tập kích nhóm Thạch Hạo","text":"Sư tử già dùng Sư tử Hống đánh rơi pháp khí của nhóm Tiêu Thiên và làm một số pháp khí nổ tung.","anchor":"thần thông sư tử hống lao ra, những pháp khí kia đều bị đánh rơi"}]},"capNhatToi":"@c0554","nguon":["@c0554","@c0745","@c0831","@c1135","@c1171","@c1279"]},{"id":"bao-thuat-hoa-chim-tuoc","name":"Bảo thuật hóa chim tước","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"Không rõ","hePhai":"Không rõ","soHuu":["Thạch Hạo"],"blurb":"Bảo thuật giúp Thạch Hạo hóa phù văn thành chim tước đỏ đậm để lấy vật từ xa.","detail":"Thạch Hạo dùng chim tước do phù văn hóa thành ngậm mảnh Nguyên Thủy Chân Cốt khỏi tế đàn, tránh trực tiếp chạm vào các dị vật nguy hiểm xung quanh.","congNang":["Hóa phù văn thành chim tước để thu lấy vật thể từ xa tại tế đàn Tây Lăng."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0555","tangDatToi":"","trangThai":"thi triển"}],"tabs":{"tienTrinh":[{"chuong":"@c0555","loai":"thi triển","importance":"normal","giaiDoan":"Lấy chân cốt","text":"Thạch Hạo hóa phù văn thành chim tước đỏ đậm và dùng nó lấy mảnh chân cốt cuối cùng khỏi tế đàn.","anchor":"Một con chim tước nhỏ màu đỏ đậm hiện ta trên tế đàn"}]},"capNhatToi":"@c0555","nguon":["@c0555"]},{"id":"than-thong-bay-muoi-hai-bien-hoa","name":"Thần thông bảy mươi hai biến hóa","cn":"","loai":"than-thong","loaiLabel":"Thần thông biến hóa","phamCap":"Không rõ","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Thần thông giúp người thi triển biến đổi hình dạng để che giấu và xâm nhập.","detail":"Thạch Hạo vận dụng thần thông này hóa thành một con muỗi, nhờ đó âm thầm tiến vào Bất Lão sơn.","thuocTinh":"Biến hóa","uyLuc":"Có thể biến người thi triển thành sinh vật nhỏ để bí mật xâm nhập.","dacDiem":"Thạch Hạo từng dùng để hóa thành muỗi.","chieuTieuBieu":["Hóa thành muỗi"],"congNang":["Biến thành sinh vật nhỏ để ẩn giấu và xâm nhập."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0556","tangDatToi":"Có thể thi triển","trangThai":"đang tu"}],"trangThai":"Đang được sử dụng","capNhatToi":"@c0556","tabs":{"tienTrinh":[{"chuong":"@c0556","loai":"thi triển","importance":"normal","giaiDoan":"Hóa thành muỗi","text":"Thạch Hạo thi triển thần thông, hóa thành một con muỗi để âm thầm xâm nhập Bất Lão sơn.","anchor":"dùng thần thông bảy mươi hai biến hóa hóa thành một con muỗi"}]},"nguon":["@c0556"]},{"id":"tran-phap-bat-lao-son","name":"Trận pháp Bất Lão sơn","cn":"","loai":"khac","loaiLabel":"Trận pháp phòng hộ","phamCap":"Không rõ","hePhai":"Bất Lão sơn","soHuu":[],"blurb":"Trận pháp phòng hộ bao quanh Bất Lão sơn và che chắn khu vực trọng yếu của thế lực này.","detail":"Đả Thần Thạch biết bí mật của trận pháp và chỉ dẫn Thạch Hạo âm thầm vượt qua mà không gây động tĩnh.","thuocTinh":"Phòng hộ","dacDiem":"Tồn tại bí mật có thể bị người am hiểu trận pháp lợi dụng để lặng lẽ xâm nhập.","congNang":["Bảo vệ và ngăn người ngoài tiến vào Bất Lão sơn."],"trangThai":"Đang vận hành","capNhatToi":"@c0556","tabs":{"tienTrinh":[{"chuong":"@c0556","loai":"xuất hiện","importance":"normal","giaiDoan":"Bị bí mật vượt qua","text":"Đả Thần Thạch chỉ rõ bí mật của trận pháp, giúp Thạch Hạo lặng lẽ xâm nhập Bất Lão sơn.","anchor":"dựa vào sự chỉ điểm của Đả Thần Thạch về bí mật của trận pháp này"}]},"nguon":["@c0556"]},{"id":"tran-phap-lien-lac-cua-lieu-than","name":"Trận pháp liên lạc của Liễu Thần","cn":"","loai":"bi-thuat","loaiLabel":"Trận pháp truyền tống","phamCap":"","hePhai":"Liễu Thần","soHuu":["Liễu Thần"],"blurb":"Trận pháp do Liễu Thần bố trí, chứa một tế đàn lớn có thể liên lạc với bên ngoài.","detail":"Trận pháp tạo điều kiện cho Thạch Hạo di chuyển thuận tiện giữa hoàng cung Thạch quốc và Thạch thôn.","thuocTinh":"Liên lạc và truyền tống","nguonGoc":"Do Liễu Thần bố trí","congNang":["Liên lạc với bên ngoài và hỗ trợ Thạch Hạo di chuyển qua tế đàn lớn."],"dacDiem":"Có một tế đàn cỡ lớn làm đầu mối liên lạc.","nguoiTu":[{"ten":"Liễu Thần","tuChuong":"@c0557","tangDatToi":"Người bố trí","trangThai":"đã bố trí"}],"trangThai":"Đang vận hành","capNhatToi":"@c0557","tabs":{"tienTrinh":[{"chuong":"@c0557","loai":"xuất hiện","importance":"normal","giaiDoan":"Hỗ trợ di chuyển","text":"Trận pháp được xác nhận có tế đàn lớn liên lạc với bên ngoài và giúp Thạch Hạo di chuyển thuận tiện.","anchor":"Trận pháp mà Liễu Thần bố trí có một tế đàn cỡ lớn, có thể liên lạc với bên ngoài nhằm giúp thuận tiện cho việc di chuyển cho Thạch Hạo."}]},"nguon":["@c0557"]},{"id":"ngu-hoa-thuat","name":"Ngự Hỏa thuật","cn":"","loai":"than-thong","loaiLabel":"Thuật ngự hỏa","phamCap":"Không rõ","hePhai":"Hỏa đạo","soHuu":["Hỏa Vân Tiên"],"blurb":"Thuật ngự hỏa của Hỏa Vân Tiên từng được xưng là đứng đầu thiên hạ.","detail":"Thành tựu chuyên biệt của Hỏa Vân Tiên trong thuật này vẫn giữ vị trí cao nhất sau nhiều vạn năm. Trình độ Hỏa đạo của Thạch Hạo chưa đủ để phá kỷ lục ấy.","thuocTinh":"Hỏa đạo","uyLuc":"Thành tựu của Hỏa Vân Tiên duy trì kỷ lục nhiều vạn năm mà Thạch Hạo chưa thể phá.","dacDiem":"Chú trọng năng lực điều khiển hỏa diễm ở trình độ cực cao.","nguoiTu":[{"ten":"Hỏa Vân Tiên","tuChuong":"@c0559","tangDatToi":"Đứng đầu thiên hạ","trangThai":"đã đạt thành tựu kỷ lục"}],"tabs":{"tienTrinh":[{"chuong":"@c0559","loai":"nhắc tới","importance":"bridge","giaiDoan":"Kỷ lục trường tồn","text":"Thành tựu Ngự Hỏa thuật của Hỏa Vân Tiên vẫn giữ vị trí đứng đầu sau nhiều vạn năm.","anchor":"Ngự Hỏa thuật của hắn được xưng là đứng đầu trong thiên hạ"}]},"capNhatToi":"@c0559","nguon":["@c0559"]},{"id":"than-tien-thuat","name":"Thần Tiễn thuật","cn":"","loai":"bi-thuat","loaiLabel":"Kỳ thuật sát phạt","phamCap":"Không rõ","hePhai":"Không rõ","soHuu":["Phượng Vũ"],"blurb":"Kỳ thuật sát phạt giúp Phượng Vũ hóa thân thành một mũi tên bạc cực tốc.","detail":"Phượng Vũ căng cứng thân thể, hóa thành thần tiễn bạc rồi liên tục đổi hướng và xung kích trong hư không. Thuật này được phối hợp với Súc Địa Thành Thốn để gia tăng tốc độ.","thuocTinh":"Cực tốc và sát phạt","uyLuc":"Tạo thế xung kích mạnh bằng cách biến toàn thân người thi triển thành thần tiễn.","dacDiem":"Người thi triển có thể liên tục đổi hướng trong lúc lao đi.","congNang":["Biến thân thể thành thần tiễn bạc cực tốc để xung kích đối thủ @c0561."],"nguoiTu":[{"ten":"Phượng Vũ","tuChuong":"@c0561","tangDatToi":"Đã thi triển","trangThai":"đang tu"}],"tabs":{"tienTrinh":[{"chuong":"@c0561","loai":"thi triển","importance":"normal","giaiDoan":"Thân hóa thần tiễn","text":"Phượng Vũ hóa thành mũi tên bạc, liên tục đổi hướng và xung kích Thạch Hạo.","anchor":"cả người dường như là một mũi tên rời cung vậy"}]},"capNhatToi":"@c0561","nguon":["@c0561"]},{"id":"thien-tien-quang","name":"Thiên tiên quang","cn":"","loai":"than-thong","loaiLabel":"Bảo thuật hộ thể","phamCap":"Không rõ","hePhai":"Không rõ","soHuu":["Phượng Vũ"],"blurb":"Thiên tiên quang là lớp ánh sáng hộ thể do Phượng Vũ tu thành, có tác dụng gia trì sức mạnh và bảo vệ thân thể trong cận chiến. Nhờ đó, nàng có thể đối kháng trực diện với Thạch Hạo.","detail":"Thiên tiên quang bao phủ cơ thể Phượng Vũ bằng một lớp ánh sáng đặc biệt, giúp gia trì sức mạnh thân thể và bảo vệ nàng khi cận chiến. Phượng Vũ xác nhận đây là năng lực do chính nàng tu thành; với trạng thái này, nàng có thể giao chiến cận thân ngang ngửa với Thạch Hạo dù không thuần túy dựa vào luyện thể. Nàng mô tả trạng thái ấy là vạn pháp bất xâm và thân thể bất hủ. @c0561","thuocTinh":"Hộ thể","uyLuc":"Gia trì thân thể đủ để Phượng Vũ giao chiến cận thân ngang ngửa với Thạch Hạo.","dacDiem":"Bao phủ cơ thể bằng một lớp ánh sáng đặc biệt có khả năng bảo vệ thân thể.","congNang":["Gia trì sức mạnh thân thể và bảo vệ người tu trong cận chiến. @c0561"],"nguoiTu":[{"ten":"Phượng Vũ","tuChuong":"@c0561","tangDatToi":"Đã tu thành","trangThai":"đang tu"}],"tabs":{"tienTrinh":[{"chuong":"@c0561","loai":"hé lộ tầng-chiêu","importance":"major","giaiDoan":"Hé lộ năng lực hộ thể","text":"Phượng Vũ xác nhận lớp ánh sáng bảo vệ thân thể mình là Thiên tiên quang do nàng tu thành.","anchor":"đây chính là Thiên tiên quang mà ta tu thành"}]},"capNhatToi":"@c0561","nguon":["@c0561"]},{"id":"suc-manh-chi-ton-cot","name":"Sức mạnh Chí Tôn cốt","cn":"","loai":"than-thong","loaiLabel":"Thiên phú thần thuật","phamCap":"Không rõ","hePhai":"Chí Tôn cốt","soHuu":["Thạch Hạo"],"blurb":"Sức mạnh Chí Tôn cốt là thiên phú thần thuật phát sinh từ Chí Tôn cốt của Thạch Hạo. Khi thi triển, năng lực này phóng thích vô tận phù văn, có thể áp chế thần thuật của đối thủ và khiến Phượng Vũ nhanh chóng teo nhỏ thành hình dáng bé gái tám, chín tuổi. (+) Huyết dịch Chí tôn thức tỉnh giúp Thạch Hạo tăng khả năng chịu đựng ánh lửa đại đạo. [CAN-SOAT-GOP]","detail":"Thạch Hạo vận dụng sức mạnh Chí Tôn cốt trước khi Phượng Vũ hoàn tất cấm thuật. Vô tận phù văn tỏa ra từ cơ thể hắn, ngăn thiên phú thần thuật nơi mi tâm Phượng Vũ khuếch tán, đồng thời khiến thân thể nàng teo nhỏ thành bé gái tám, chín tuổi. @c0561","thuocTinh":"Áp chế và biến đổi thân thể","uyLuc":"Có thể chặn thần thuật của Phượng Vũ trước khi hoàn tất và khiến nàng nhanh chóng teo nhỏ thành bé gái tám, chín tuổi. @c0561","dacDiem":"Khi phát động, vô tận phù văn tỏa ra từ Thạch Hạo. @c0561","congNang":["Phóng thích phù văn để áp chế cấm thuật và thiên phú thần thuật của đối thủ. @c0561","Khiến Phượng Vũ teo nhỏ thành hình dáng bé gái tám, chín tuổi. @c0561"],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0561","tangDatToi":"Đã vận dụng trong chiến đấu","trangThai":"đang tu"}],"tabs":{"tienTrinh":[{"chuong":"@c0561","loai":"thi triển","importance":"major","giaiDoan":"Áp chế Phượng Vũ","text":"Thạch Hạo vận dụng sức mạnh Chí Tôn cốt, ngăn Phượng Vũ phát động thần thuật và biến nàng thành bé gái.","anchor":"lập tức vận dụng sức mạnh Chí Tôn cốt, vô tận phù văn tỏa ra"}]},"capNhatToi":"@c0561","nguon":["@c0561","@c0867"]},{"id":"binh-giai","name":"Binh giải","cn":"","loai":"bi-thuat","loaiLabel":"Bí thuật","phamCap":"Không rõ","hePhai":"Tiên viện","soHuu":["Phượng Vũ"],"blurb":"Bí pháp cho phép Phượng Vũ thủ tiêu thân thể trong Hư Thần giới để thoát khỏi giam cầm và trở về hiện thực.","detail":"Khi bị Thạch Hạo phong ấn tại đàn Đồng Tước, Phượng Vũ dùng Binh giải để hóa thành mưa ánh sáng, thoát khỏi tay đối phương và để lại một thanh tiểu kiếm.","thuocTinh":"Bí pháp thoát thân","congNang":["Thủ tiêu thân thể trong Hư Thần giới để thoát khỏi giam cầm và trở về hiện thực."],"nguoiTu":[{"ten":"Phượng Vũ","tuChuong":"@c0562","tangDatToi":"Đã sử dụng","trangThai":"đang nắm giữ"}],"trangThai":"Đang lưu truyền","capNhatToi":"@c0562","tabs":{"tienTrinh":[{"chuong":"@c0562","loai":"thi triển","importance":"normal","giaiDoan":"Phượng Vũ sử dụng","text":"Phượng Vũ dùng Binh giải để thủ tiêu thân thể trong Hư Thần giới, hóa thành mưa ánh sáng và thoát khỏi phong ấn của Thạch Hạo.","anchor":"đây là binh giải, dùng bí pháp để thủ tiêu bản thân"}]},"nguon":["@c0562"]},{"id":"nam-ly-than-hoa","name":"Nam Ly thần hỏa","cn":"","loai":"than-thong","loaiLabel":"Thần thông hỏa hệ","phamCap":"Không rõ","hePhai":"Hỏa hệ","soHuu":[],"blurb":"Thần thông hóa người thi triển thành người lửa khổng lồ và phát ra đại hỏa sáng rực.","detail":"Một cường giả dùng Nam Ly thần hỏa để xua sương mù trên đàn Đồng Tước, nhưng ngọn lửa bị Côn Ngư mang sức mạnh Thái Âm của Thạch Hạo phá tan.","congNang":["Triển khai đại hỏa để chiếu sáng và xua tan sương mù."],"uyLuc":"Có thể tạo thành biển lửa sáng rực, nhưng không chống nổi sức mạnh Thái Âm do Thạch Hạo diễn hóa.","tabs":{"tienTrinh":[{"chuong":"@c0563","loai":"thi triển","importance":"normal","giaiDoan":"Đối đầu Thạch Hạo","text":"Nam Ly thần hỏa được triển khai để xua sương mù nhưng bị Côn Ngư Thái Âm phá tan.","anchor":"có một cường giả triển khai Nam Ly thần hỏa, bốn phía sáng rực"}]},"capNhatToi":"@c0563","nguon":["@c0563"]},{"id":"dai-tran-tran-ky-hoa-van-dong","name":"Đại trận trận kỳ Hỏa Vân Động","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Không rõ","hePhai":"Hỏa Vân Động","soHuu":["Hỏa Vân Động"],"blurb":"Đại trận do nhiều Linh Viên của Hỏa Vân Động đồng thời vận dụng trận kỳ để bố trí.","detail":"Khi được mở, đại trận khiến thiên địa biến hóa và vây giữ mục tiêu. Thạch Hạo phối hợp pháp môn Côn Bằng với kiếm ý cây cỏ để chém nát các trận kỳ, khiến trận pháp tan rã.","yeuCau":"Cần nhiều người đồng thời điều khiển các trận kỳ.","congNang":["Kết hợp nhiều trận kỳ để làm thiên địa biến hóa và vây bắt mục tiêu."],"nguoiTu":[],"tabs":{"tienTrinh":[{"chuong":"@c0563","loai":"thi triển","importance":"normal","giaiDoan":"Vây bắt Hạo Thiên","text":"Các Linh Viên của Hỏa Vân Động mở đại trận vây bắt Thạch Hạo, nhưng toàn bộ đội hình bị hắn phá tan.","anchor":"tất cả đều nắm trận kỳ, trong lúc nhất thời cả thiên địa biến hóa, đại trận được mở ra"}]},"trangThai":"Bị phá","capNhatToi":"@c0563","nguon":["@c0563"]},{"id":"bao-thuat-chan-hoang","name":"Bảo thuật Chân Hoàng","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Bảo thuật giúp Thạch Hạo hóa ra đôi tiên sí Chân Hoàng đỏ rực. Thức thứ nhất được dùng để ngăn chùm thần quang năm màu của Chân Lôn.","detail":"Khi thi triển thức thứ nhất, Thạch Hạo tạo một đôi tiên sí đỏ rực mang khí thế dục hỏa trùng sinh. Đôi cánh chắn trước người và đối kháng với phù văn năm màu bắn ra từ mắt dọc của Chân Lôn.","thuocTinh":"Chân Hoàng, hỏa","uyLuc":"Đôi tiên sí đỏ rực có thể đối kháng thần quang năm màu của Chân Lôn.","dacDiem":"Thức thứ nhất hóa thành đôi cánh Chân Hoàng dùng để phòng ngự.","chieuTieuBieu":["Thức thứ nhất"],"cacTang":[{"ten":"Thức thứ nhất","moTa":"Hóa đôi tiên sí đỏ rực chắn trước người.","chuong":"@c0564"}],"congNang":["Hóa cánh Chân Hoàng để phòng ngự và đối kháng thần quang."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0564","tangDatToi":"Thức thứ nhất","trangThai":"thi-trien"}],"trangThai":"đang được Thạch Hạo sử dụng","capNhatToi":"@c0564","tabs":{"tienTrinh":[{"chuong":"@c0564","loai":"hé lộ tầng-chiêu","importance":"normal","giaiDoan":"Thức thứ nhất","text":"Thạch Hạo thi triển thức thứ nhất, hóa đôi tiên sí Chân Hoàng đỏ rực để chặn thần quang năm màu của Chân Lôn.","anchor":"đó chính là thức thứ nhất của bảo thuật Chân Hoàng, một đôi tiên sí đỏ rực ngang trời cao"}]},"nguon":["@c0564"]},{"id":"chien-mau-ngung-huyet-cua-chan-lon","name":"Chiến mâu ngưng huyết của Chân Lôn","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Thần thông thiên phú","phamCap":"","hePhai":"Linh tộc","soHuu":["Chân Lôn"],"blurb":"Thần thông thiên phú khiến máu ngưng thành chiến mâu đỏ đậm trong lòng bàn tay trái Chân Lôn. Chiến mâu có sức xuyên phá mạnh nhưng được chính Chân Lôn thừa nhận là kém xa năng lực tương tự của Chân Cổ.","detail":"Máu của Chân Lôn tụ lại và hóa thành một thanh chiến mâu nhô lên từ lòng bàn tay trái. Trong cuộc giao chiến tại đàn Đồng Tước, mũi mâu làm bàn tay Thạch Hạo bị thương và suýt xuyên thủng lòng bàn tay.","thuocTinh":"Máu","nguonGoc":"Thần thông thiên phú của Chân Lôn","uyLuc":"Có thể phá thân thể Thạch Hạo và suýt xuyên thủng lòng bàn tay.","dacDiem":"Chiến mâu đỏ đậm hình thành trực tiếp từ máu trong lòng bàn tay trái.","chieuTieuBieu":["Chiến mâu ngưng huyết"],"congNang":["Ngưng tụ máu thành chiến mâu để xuyên phá thân thể mục tiêu."],"nguoiTu":[{"ten":"Chân Lôn","tuChuong":"@c0564","tangDatToi":"","trangThai":"thi-trien"}],"trangThai":"đang được Chân Lôn sử dụng","capNhatToi":"@c0564","tabs":{"tienTrinh":[{"chuong":"@c0564","loai":"thi triển","importance":"normal","giaiDoan":"Chiến mâu ngưng huyết","text":"Chân Lôn ngưng tụ máu thành chiến mâu, dùng nó làm bàn tay Thạch Hạo bị thương trong cuộc giao chiến.","anchor":"đó là một thanh mâu từ từ nhô lên trong lòng bàn tay của hắn, uy năng vô lượng"}]},"nguon":["@c0564"]},{"id":"than-an-nhat-nguyet","name":"Thần ấn nhật nguyệt","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"Không rõ","hePhai":"Tộc Hỏa Kim","soHuu":["Đằng Nhất"],"blurb":"Bảo thuật diễn hóa thần nguyệt, đại nhật và vô số sao trời để trấn áp đối thủ.","detail":"Đằng Nhất dùng tay trái diễn hóa thần nguyệt, tay phải diễn hóa đại nhật, rồi dẫn dị tượng nhật nguyệt cùng sao trời giáng xuống Thạch Hạo. Dị tượng bị hai khí Âm Dương phá nát.","congNang":["Diễn hóa nhật nguyệt và sao trời để trấn áp đối thủ."],"nguoiTu":[{"ten":"Đằng Nhất","tuChuong":"@c0565","tangDatToi":"Có thể thi triển","trangThai":"đang tu"}],"tabs":{"tienTrinh":[{"chuong":"@c0565","loai":"thi triển","importance":"normal","giaiDoan":"Đối chiến tại đàn Đồng Tước","text":"Đằng Nhất diễn hóa nhật nguyệt và vô số sao trời để trấn áp Thạch Hạo, nhưng dị tượng bị hai khí Âm Dương phá giải.","anchor":"Hai tay của hắn nắm chặt thần ấn nhật nguyệt, thiên địa lật úp, trong hư không hiện lên vô số ngôi sao đồng thời giáng lâm xuống"}]},"capNhatToi":"@c0565","nguon":["@c0565"]},{"id":"hoa-kim-bao-binh-an","name":"Hỏa Kim Bảo Bình Ấn","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Tuyệt học thời Thái Cổ","hePhai":"Tộc Hỏa Kim","soHuu":["Đằng Nhất"],"blurb":"Hỏa Kim Bảo Bình Ấn là tuyệt học thời Thái Cổ do tộc Hỏa Kim tham khảo pháp quyết của nhiều tộc để khai sáng. Sau một thời gian dần thất truyền, công pháp được Đằng Nhất tái hiện, dùng bảo bình đỏ cùng hỏa thể và kim thể để giao chiến với Thạch Hạo.","detail":"Khi thi triển Hỏa Kim Bảo Bình Ấn, người dùng ngưng tụ một bảo bình đỏ trên đầu, từ đó phun ra nhiều loại thiên hỏa mang hình thái khác nhau và ẩn chứa một phần áo nghĩa của các đại cường tộc. Đằng Nhất từng dùng bảo bình phóng thiên hỏa uy hiếp Thạch Hạo, sau đó đồng thời triển khai cả hỏa thể lẫn kim thể trong giao chiến; hỏa thể có thể diễn hóa chim thần và nhiều loại thiên hỏa, còn kim thể phóng ra kiếm khí dày đặc.","nguonGoc":"Do tộc Hỏa Kim thời Thái Cổ tham khảo pháp quyết của nhiều tộc rồi khai sáng.","uyLuc":"Nhiều loại thiên hỏa đồng thời xuất hiện khiến Thạch Hạo nhận định chỉ một sai lầm nhỏ cũng có thể dẫn đến tử vong.","dacDiem":"Ngưng tụ bảo bình đỏ trên đầu, phun ra các thiên hỏa có hình thái khác nhau, đồng thời có thể triển khai hỏa thể và kim thể.","chieuTieuBieu":["Phun thần hỏa Nam Ly","Phun tinh hỏa thái dương","Phun niết bàn sinh hỏa"],"congNang":["Phun ra nhiều loại thiên hỏa để công kích và áp chế đối thủ. @c0565","Hỏa thể diễn hóa chim thần và nhiều loại thiên hỏa. @c0566","Kim thể phóng kiếm khí dày đặc, chém ngập mục tiêu. @c0566"],"nguoiTu":[{"ten":"Đằng Nhất","tuChuong":"@c0565","tangDatToi":"Có thể triển khai cả hỏa thể và kim thể","trangThai":"Đã thi triển"}],"tabs":{"tienTrinh":[{"chuong":"@c0565","loai":"tái hiện","importance":"major","giaiDoan":"Tái hiện tuyệt học thất truyền","text":"Đằng Nhất tái hiện Hỏa Kim Bảo Bình Ấn và dùng bảo bình phun ra nhiều loại thiên hỏa để uy hiếp Thạch Hạo.","anchor":"Chỉ trong nháy mắt, bảo bình trên đầu Đằng Nhất chấn động rồi phun trào nhiều loại thiên hỏa"},{"chuong":"@c0566","loai":"thi triển","importance":"normal","giaiDoan":"Hỏa thể và kim thể","text":"Đằng Nhất triển khai cả hỏa thể lẫn kim thể của Hỏa Kim Bảo Bình Ấn để giao chiến với Thạch Hạo, nhưng bảo bình cuối cùng bị Âm Dương Nghịch Chuyển đánh vỡ.","anchor":"Hỏa Kim Bảo Bình Ấn, tự nhiên được phân làm hỏa và kim"}]},"trangThai":"Được Đằng Nhất tái hiện","capNhatToi":"@c0565","nguon":["@c0565","@c0566"]},{"id":"hai-khi-am-duong","name":"Hai khí Âm Dương","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Không rõ","hePhai":"Côn Bằng","soHuu":["Thạch Hạo"],"blurb":"Sức mạnh âm dương được Thạch Hạo vận chuyển để phá dị tượng và đối kháng thiên hỏa.","detail":"Thạch Hạo bùng phát hai khí Âm Dương, hợp nhất hai mặt tối và sáng để phá nát nhật nguyệt cùng sao trời do Đằng Nhất diễn hóa. Sau đó nó tiếp tục vận chuyển sức mạnh này để chống lại các thiên hỏa từ Hỏa Kim Bảo Bình Ấn.","thuocTinh":"Âm dương","congNang":["Phá dị tượng nhật nguyệt và sao trời.","Đối kháng nhiều loại thiên hỏa."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0565","tangDatToi":"Có thể hợp nhất âm dương để chiến đấu","trangThai":"đang tu"}],"tabs":{"tienTrinh":[{"chuong":"@c0565","loai":"thi triển","importance":"normal","giaiDoan":"Đối kháng thần ấn và thiên hỏa","text":"Thạch Hạo bùng phát hai khí Âm Dương để phá dị tượng nhật nguyệt, rồi tiếp tục dùng chúng chống lại các thiên hỏa.","anchor":"Thạch Hạo một tay chỉ trời, một tay chỉ đất, lập tức bùng nổ ra hai khí Âm Dương"}]},"capNhatToi":"@c0565","nguon":["@c0565"]},{"id":"than-hoa-nam-ly","name":"Thần hỏa Nam Ly","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Hỏa thuật","phamCap":"Thiên hỏa","hePhai":"Hỏa Kim Bảo Bình Ấn","soHuu":[],"blurb":"Một loại thiên hỏa được Hỏa Kim Bảo Bình Ấn phun ra.","detail":"Thần hỏa Nam Ly che ngợp bầu trời, hóa thành một con hỏa thước bay lượn và phát tiếng kêu lớn khiến các tộc kinh sợ.","thuocTinh":"Hỏa","dacDiem":"Hóa thành hỏa thước.","congNang":["Hóa thành hỏa thước để uy hiếp và công kích đối thủ."],"tabs":{"tienTrinh":[{"chuong":"@c0565","loai":"xuất hiện","importance":"normal","giaiDoan":"Được Hỏa Kim Bảo Bình Ấn phun ra","text":"Thần hỏa Nam Ly hóa thành hỏa thước che ngợp bầu trời và uy hiếp các tộc.","anchor":"Thần hỏa Nam Ly, che ngợp bầu trời, một con hỏa thước bay lượn phát ra tiếng kêu lớn, kinh sợ các tộc."}]},"capNhatToi":"@c0565","nguon":["@c0565"]},{"id":"tinh-hoa-thai-duong","name":"Tinh hỏa thái dương","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Hỏa thuật","phamCap":"Thiên hỏa","hePhai":"Hỏa Kim Bảo Bình Ấn","soHuu":[],"blurb":"Một loại thiên hỏa hóa thành Kim Ô ba chân mang khí hoàng kim.","detail":"Tinh hỏa thái dương được Hỏa Kim Bảo Bình Ấn phun ra, diễn hóa thành Kim Ô giương cánh và lao về phía Thạch Hạo.","thuocTinh":"Hỏa và thái dương","dacDiem":"Hóa thành Kim Ô ba chân mang khí hoàng kim.","congNang":["Diễn hóa Kim Ô ba chân để lao giết đối thủ."],"tabs":{"tienTrinh":[{"chuong":"@c0565","loai":"xuất hiện","importance":"normal","giaiDoan":"Được Hỏa Kim Bảo Bình Ấn phun ra","text":"Tinh hỏa thái dương hóa thành Kim Ô ba chân mang khí hoàng kim và lao về phía Thạch Hạo.","anchor":"Tinh hỏa thái dương, một con Kim Ô giương cánh, khí hoàng kim tràn ngập, ba châm liệt thiên địa, vô giết về phía Thạch Hạo."}]},"capNhatToi":"@c0565","nguon":["@c0565"]},{"id":"niet-ban-sinh-hoa","name":"Niết bàn sinh hỏa","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Hỏa thuật","phamCap":"Thiên hỏa","hePhai":"Hỏa Kim Bảo Bình Ấn","soHuu":[],"blurb":"Một loại thiên hỏa diễn hóa Chân Hoàng dục hỏa trùng sinh.","detail":"Niết bàn sinh hỏa sôi trào và bốc cháy, hóa thành Chân Hoàng có cánh chim rực rỡ. Hình thái này dục hỏa trùng sinh và liên tục mạnh lên.","thuocTinh":"Hỏa và niết bàn","dacDiem":"Hóa thành Chân Hoàng dục hỏa trùng sinh.","congNang":["Diễn hóa Chân Hoàng dục hỏa trùng sinh để công kích."],"tabs":{"tienTrinh":[{"chuong":"@c0565","loai":"xuất hiện","importance":"normal","giaiDoan":"Được Hỏa Kim Bảo Bình Ấn phun ra","text":"Niết bàn sinh hỏa hóa thành Chân Hoàng dục hỏa trùng sinh và tiếp tục mạnh lên.","anchor":"Niết bàn sinh hỏa, sôi trào và bốc cháy, ánh sáng chói mắt, một con Chân Hoàng hiện ra, cánh chim xinh đẹp, dục hỏa trùng sinh"}]},"capNhatToi":"@c0565","nguon":["@c0565"]},{"id":"hoa-kim-bao-binh-vo-luong-tram","name":"Hỏa Kim Bảo Bình Vô Lượng Trảm","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Chiêu thức","phamCap":"Chiêu thức thuộc kim thể của Hỏa Kim Bảo Bình Ấn","hePhai":"Tộc Hỏa Kim","soHuu":["Đằng Nhất"],"blurb":"Chiêu thức do Đằng Nhất thi triển từ kim thể của Hỏa Kim Bảo Bình Ấn. Bảo bình bạch kim phóng ra hàng nghìn hàng vạn tia kiếm khí nhằm chém ngập đối thủ.","detail":"Đằng Nhất cầm bảo bình bạch kim và phát động một biển kiếm khí dày đặc tấn công Thạch Hạo. Chiêu thức bị hai khí Âm Dương hợp nhất và nghịch chuyển về trạng thái gần hỗn độn phá giải.","thuocTinh":"Kim","uyLuc":"Phóng hàng nghìn hàng vạn tia kiếm khí dày đặc như biển.","chieuTieuBieu":["Biển kiếm khí từ bảo bình bạch kim"],"nguoiTu":[{"ten":"Đằng Nhất","tuChuong":"@c0566","tangDatToi":"Đã thi triển","trangThai":"Đã thi triển"}],"congNang":["Phóng một lượng lớn kiếm khí để bao phủ và chém ngập mục tiêu."],"capNhatToi":"@c0566","tabs":{"tienTrinh":[{"chuong":"@c0566","loai":"thi triển","importance":"normal","giaiDoan":"Chiêu kim thể","text":"Đằng Nhất dùng bảo bình bạch kim phóng biển kiếm khí tấn công Thạch Hạo.","anchor":"Hỏa Kim Bảo Bình Vô Lượng Trảm!\" Đằng Nhất hét lớn"}]},"nguon":["@c0566"]},{"id":"am-duong-nghich-chuyen","name":"Âm Dương Nghịch Chuyển","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Không rõ","hePhai":"Hai khí Âm Dương","soHuu":["Thạch Hạo"],"blurb":"Thần thông hợp nhất hai khí Âm Dương và nghịch chuyển chúng về trạng thái gần hỗn độn. Thạch Hạo dùng pháp này đánh vỡ kim thể của Hỏa Kim Bảo Bình Ấn.","detail":"Khi đối mặt biển kiếm khí của Đằng Nhất, Thạch Hạo dung hợp hai khí Âm Dương. Phù văn kèm theo khí hỗn độn xuất hiện và phá vỡ bảo bình của đối thủ.","thuocTinh":"Âm Dương và khí hỗn độn","uyLuc":"Đánh vỡ bảo bình đang triển khai Hỏa Kim Bảo Bình Vô Lượng Trảm.","dacDiem":"Hợp nhất âm dương rồi nghịch chuyển về trạng thái gần hỗn độn.","nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0566","tangDatToi":"Đã thi triển","trangThai":"Đang nắm giữ"}],"congNang":["Dung hợp hai khí Âm Dương.","Nghịch chuyển âm dương để sinh ra phù văn đi kèm khí hỗn độn."],"capNhatToi":"@c0566","tabs":{"tienTrinh":[{"chuong":"@c0566","loai":"thi triển","importance":"normal","giaiDoan":"Dung hợp âm dương","text":"Thạch Hạo hợp nhất hai khí Âm Dương và đánh vỡ bảo bình của Đằng Nhất.","anchor":"khí Âm Dương dung hợp cùng nhau, nói quát to một tiếng: \"Âm Dương Nghịch Chuyển!\""}]},"nguon":["@c0566"]},{"id":"than-y-am-duong","name":"Thần y Âm Dương","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Pháp môn phòng hộ","phamCap":"Không rõ","hePhai":"Hai khí Âm Dương","soHuu":["Thạch Hạo"],"blurb":"Pháp môn phòng hộ hình thành khi hai khí Âm Dương bao phủ thân thể thành một bộ thần y đại Đạo. Lớp bảo hộ này giúp Thạch Hạo cách tuyệt Nghiệp hỏa.","detail":"Hai khí Âm Dương hóa thành y phục bao phủ toàn thân Thạch Hạo. Nghiệp hỏa nhằm vào ác niệm không thể tiếp cận, vì vậy không thể thiêu đốt hình và thần của hắn.","thuocTinh":"Âm Dương","uyLuc":"Ngăn Nghiệp hỏa tiếp cận và thiêu đốt hình thần.","dacDiem":"Hai khí Âm Dương hóa thành y phục đại Đạo bao phủ cơ thể.","nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0566","tangDatToi":"Đã thi triển","trangThai":"Đang nắm giữ"}],"congNang":["Bao phủ thân thể bằng hai khí Âm Dương.","Cách tuyệt Nghiệp hỏa khỏi hình và thần của người sử dụng."],"capNhatToi":"@c0566","tabs":{"tienTrinh":[{"chuong":"@c0566","loai":"thi triển","importance":"normal","giaiDoan":"Thần y phòng hộ","text":"Thạch Hạo dùng hai khí Âm Dương hóa thành thần y để ngăn Nghiệp hỏa chạm tới thân thể.","anchor":"hai khí này bao phủ lấy cơ thể nó rồi hóa thành một bộ thần y âm dương khoác trên người"}]},"nguon":["@c0566"]},{"id":"nghiep-hoa","name":"Nghiệp hỏa","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Hỏa thuật","phamCap":"Không rõ","hePhai":"Hỏa Kim Bảo Bình Ấn","soHuu":["Đằng Nhất"],"blurb":"Ngọn lửa đỏ như máu xuất hiện sau khi các chim thần do Hỏa Kim Bảo Bình Ấn diễn hóa đồng quy vu tận. Nó nhắm vào ác niệm và lỗi lầm, có khả năng thiêu diệt cả hình lẫn thần.","detail":"Nghiệp hỏa được sinh ra từ vụ tự hủy của những chim thần do bảo bình diễn hóa. Ngọn lửa có thể tịnh hóa lệ khí và thiêu đốt ác niệm, nhưng không vượt qua được thần y Âm Dương của Thạch Hạo.","thuocTinh":"Hỏa","nguonGoc":"Sinh ra sau khi các chim thần do Hỏa Kim Bảo Bình Ấn diễn hóa đồng quy vu tận.","uyLuc":"Có khả năng khiến mục tiêu hình thần đều diệt.","dacDiem":"Nhằm vào ác niệm, lệ khí và lỗi lầm của mục tiêu.","nguoiTu":[{"ten":"Đằng Nhất","tuChuong":"@c0566","tangDatToi":"Dẫn phát qua Hỏa Kim Bảo Bình Ấn","trangThai":"Đã thi triển"}],"congNang":["Thiêu đốt ác niệm và lỗi lầm.","Tịnh hóa lệ khí và có thể hủy diệt cả hình lẫn thần."],"capNhatToi":"@c0566","tabs":{"tienTrinh":[{"chuong":"@c0566","loai":"thi triển","importance":"normal","giaiDoan":"Sinh ra từ chim thần tự hủy","text":"Nghiệp hỏa xuất hiện sau khi các chim thần đồng quy vu tận, nhưng bị thần y Âm Dương của Thạch Hạo cách tuyệt.","anchor":"nghiệp hỏa có thể đốt cháy các loại lỗi lầm trên thế gian"}]},"nguon":["@c0566"]},{"id":"chi-ton-thuat-cua-thach-hao","name":"Chí Tôn thuật của Thạch Hạo","cn":"","aliases":["Luân hồi"],"loai":"than-thong","loaiLabel":"Thần thuật thiên phú","phamCap":"Chí Tôn thuật","hePhai":"Chí Tôn cốt","soHuu":["Thạch Hạo"],"blurb":"Chí Tôn thuật của Thạch Hạo là thần thuật thiên phú được thai nghén trong Chí Tôn cốt, biểu hiện qua các ký hiệu thần bí phóng trực tiếp từ vùng xương ngực. Thuật từng nghiền nát hóa thân Đằng Nhất thành tro trong một đòn, đồng thời được vận dụng dưới dạng Luân hồi để phối hợp với pháp môn Côn Bằng trong chiến đấu. (+) Hai loại phù văn trời sinh của Thạch Hạo bắt đầu quấn chặt, cộng hưởng và dần dung hợp làm một. [CAN-SOAT-GOP] (+) Chí Tôn thuật Luân hồi được Thạch Hạo vận chuyển qua kiếm thai Đại La để làm đối thủ nhanh chóng già yếu. [CAN-SOAT-GOP] (+) Pháp thứ hai do Chí tôn cốt của Thạch Hạo sinh ra được xác nhận là Luân Hồi, có thể diễn dịch lực lượng thời gian. [CAN-SOAT-GOP]","detail":"Chí Tôn thuật bắt nguồn từ Chí Tôn cốt của Thạch Hạo. Khi thi triển, hắn kích phát những ký hiệu thần bí từ vùng xương ngực, đánh trúng hóa thân Đằng Nhất, khiến đối phương hiện thành cây đằng rồi nổ tung thành tro và mưa ánh sáng. Về sau, Thạch Hạo vận dụng Luân hồi phối hợp với pháp môn Côn Bằng để phá thần kiếm của Hắc Lan, sau đó oanh kích Thao Thiết. @c0566 @c0674","thuocTinh":"Ký hiệu thần bí từ Chí Tôn cốt","nguonGoc":"Được thai nghén trong Chí Tôn cốt của Thạch Hạo.","uyLuc":"Một đòn kích phát ký hiệu thần bí đã nghiền nát hóa thân Đằng Nhất thành tro. @c0566","dacDiem":"Là thần thuật thiên phú được thai nghén trong Chí Tôn cốt, với ký hiệu thần bí phóng trực tiếp từ vùng xương ngực; có thể vận dụng Luân hồi phối hợp cùng pháp môn Côn Bằng. @c0566 @c0674","nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0566","tangDatToi":"Đã kích phát trong thực chiến","trangThai":"Đang nắm giữ"}],"congNang":["Phóng ký hiệu thần bí từ Chí Tôn cốt ở vùng xương ngực để công kích mục tiêu. @c0566","Nghiền nát hóa thân cây đằng của Đằng Nhất thành tro trong một đòn kích phát. @c0566","Vận dụng Luân hồi phối hợp với pháp môn Côn Bằng để phá thần kiếm của Hắc Lan, sau đó oanh kích Thao Thiết. @c0674"],"capNhatToi":"@c0566","tabs":{"tienTrinh":[{"chuong":"@c0566","loai":"thi triển","importance":"major","giaiDoan":"Kích phát trong thực chiến","text":"Thạch Hạo kích phát ký hiệu thần bí từ Chí Tôn cốt và nghiền nát hóa thân Đằng Nhất thành tro.","anchor":"Xương ngực của nó phát sáng, ký hiệu thần bí tỏa ra lập tức quét trúng Đằng Nhất"}]},"nguon":["@c0566","@c0867","@c1042","@c1125"]},{"id":"that-thap-nhi-bien","name":"Thất Thập Nhị Biến","cn":"","aliases":["Bảy mươi hai biến"],"loai":"than-thong","loaiLabel":"Thần thông biến hóa","phamCap":"Không rõ","hePhai":"","soHuu":["Thạch Hạo"],"blurb":"Thất Thập Nhị Biến là pháp môn biến hóa được Thạch Hạo vận dụng để hóa thân thành Côn Bằng. Khi kết hợp hình thái này với bảo thuật Côn Bằng, hắn có thể phát huy tốc độ và uy thế chiến đấu ở mức cao hơn. (+) Thần thông của bộ tộc Chu Yếm có thể thay đổi dung mạo. [CAN-SOAT-GOP]","detail":"Thạch Hạo tìm ra cách vận dụng Thất Thập Nhị Biến để hóa thành Côn Bằng, đồng thời phối hợp đặc tính của hình thái này với tốc độ của bảo thuật Côn Bằng. Cách vận dụng ấy giúp pháp môn không chỉ thay đổi hình thể mà còn hỗ trợ phát huy uy thế và tốc độ trong chiến đấu. @c0567","thuocTinh":"Biến hóa","uyLuc":"Có thể phối hợp với bảo thuật Côn Bằng để đẩy tốc độ và uy thế chiến đấu lên mức cao hơn. @c0567","dacDiem":"Không chỉ biến đổi hình thể mà còn cho phép Thạch Hạo phối hợp đặc tính của hình thái Côn Bằng với bảo thuật tương ứng.","chieuTieuBieu":["Hóa thành Côn Bằng"],"congNang":["Hóa thân thành Côn Bằng. @c0567","Phối hợp hình thái Côn Bằng với tốc độ của bảo thuật Côn Bằng. @c0567"],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0567","tangDatToi":"Mới tìm ra cách vận dụng hóa thành Côn Bằng","trangThai":"đang tu luyện"}],"trangThai":"Đang được Thạch Hạo vận dụng","capNhatToi":"@c0567","tabs":{"tienTrinh":[{"chuong":"@c0567","loai":"hé lộ tầng-chiêu","importance":"major","giaiDoan":"Hóa thành Côn Bằng","text":"Thạch Hạo tìm ra cách vận dụng Thất Thập Nhị Biến để hóa thành Côn Bằng và phối hợp với tốc độ của bảo thuật Côn Bằng.","anchor":"Đây là sự vận dụng của Thất Thập Nhị Biến, chỉ trong nháy mắt thân thể của nó đã hóa thành Bằng"}]},"nguon":["@c0567","@c0647"]},{"id":"kim-lien-than-phat-cua-thanh-ca","name":"Kim liên thần phạt của Thanh Ca","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Không rõ","hePhai":"Liên tộc","soHuu":["Thanh Ca"],"blurb":"Thần thông của Thanh Ca dùng kim liên và thần hỏa dẫn động đại thế thiên địa.","detail":"Thanh Ca khiến kim liên mọc trong hư không và thần hỏa, tụ đại thế thiên địa để trấn áp đối thủ. Hoa sen khổng lồ còn có thể khép lại nhằm luyện hóa người bị vây, nhưng Thanh Ca chưa đạt cảnh giới đủ để phát huy hoàn toàn sức mạnh thần phạt.","thuocTinh":"Kim liên; thần hỏa; đại thế thiên địa","yeuCau":"Sức mạnh pháp tắc này thường thuộc về người đã nhen nhóm Thần hỏa, còn Thanh Ca mới chỉ bước đầu chạm tới.","uyLuc":"Có thể tụ đại thế thiên địa để trấn áp, phán quyết và luyện hóa đối thủ.","dacDiem":"Thanh Ca chưa đủ cảnh giới để phát huy hoàn toàn thần phạt.","chieuTieuBieu":["Kim liên trấn áp","Hoa sen luyện hóa"],"congNang":["Tụ đại thế thiên địa để trấn áp đối thủ.","Dùng hoa sen khổng lồ bao bọc và luyện hóa mục tiêu."],"nguoiTu":[{"ten":"Thanh Ca","tuChuong":"@c0567","tangDatToi":"Bước đầu chấp chưởng thần phạt","trangThai":"đang tu luyện"}],"trangThai":"Đang được Thanh Ca vận dụng","capNhatToi":"@c0567","tabs":{"tienTrinh":[{"chuong":"@c0567","loai":"thi triển","importance":"normal","giaiDoan":"Thần phạt kim liên","text":"Thanh Ca dùng kim liên trong thần hỏa tụ đại thế thiên địa để trấn áp và luyện hóa Thạch Hạo nhưng cuối cùng bị phá pháp.","anchor":"Kim liên cháy hừng hực, nhưng tụ đại thế thiên địa, trong nháy mắt hắn đã thiên nhân hợp nhất, tuân theo thiên ý, chấp chưởng thần phạt, tiền hành phán quyết."}]},"nguon":["@c0567"]},{"id":"tia-chop-luyen-sinh-hon","name":"Tia chớp luyện sinh hồn","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Không rõ","hePhai":"Không rõ","soHuu":["Lão bộc của Hỗn Thiên hầu"],"blurb":"Thần thông dung hợp sinh hồn và hồn niệm vào tia chớp màu đen để công kích.","detail":"Khi được thi triển, tia chớp đen đi kèm tiếng quỷ khóc thần gào và vô số hồn ảnh. Công kích này bị kim quang của Thạch Hạo phá tan.","thuocTinh":"Lôi điện và sinh hồn","congNang":["Dùng sinh hồn cùng hồn niệm tạo thành tia chớp màu đen công kích đối phương."],"nguoiTu":[{"ten":"Lão bộc của Hỗn Thiên hầu","tuChuong":"@c0569","tangDatToi":"Không rõ","trangThai":"Đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0569","loai":"thi triển","importance":"normal","giaiDoan":"Lần đầu xuất hiện","text":"Lão bộc thi triển tia chớp đen luyện từ sinh hồn nhằm vào Thạch Hạo, nhưng công kích bị kim quang phá tan.","anchor":"một chùm tia chớp màu đen bắn ra, đi kèm là âm thành quỷ khóc thần gào"}]},"capNhatToi":"@c0569","nguon":["@c0569"]},{"id":"thien-thu","name":"Thiên thủ","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"Tây Phương giáo","soHuu":["Tượng thần mạ vàng"],"blurb":"Thần thông của Tây Phương giáo cho phép người thi triển hóa ra một nghìn cánh tay.","detail":"Tượng thần mạ vàng phối hợp Thiên thủ với kim thân để nghênh chiến Tiểu Hồng và Bóng Lông. Nhiều cánh tay bị pháp kiếm Chân Thần chém đứt trong trận chiến.","thuocTinh":"Hóa ra nhiều cánh tay","nguonGoc":"Tây Phương giáo","congNang":["Hóa ra một nghìn cánh tay để đồng thời công kích và phòng thủ."],"nguoiTu":[{"ten":"Tượng thần mạ vàng","tuChuong":"@c0570","tangDatToi":"Có thể thi triển","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0570","loai":"thi triển","importance":"normal","giaiDoan":"Thi triển phối hợp kim thân","text":"Tượng thần mạ vàng hóa ra một nghìn cánh tay và dùng kim thân gia trì để nghênh chiến Tiểu Hồng cùng Bóng Lông.","anchor":"thần thông Thiên thủ còn được gia trì bởi kim thân"}]},"capNhatToi":"@c0570","nguon":["@c0570"]},{"id":"kim-than-tay-phuong-giao","name":"Kim thân Tây Phương giáo","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"","hePhai":"Tây Phương giáo","soHuu":["Tượng thần mạ vàng"],"blurb":"Thần thông kim thân có khả năng gia trì Thiên thủ, tái sinh tay cụt và khép lại thương thế.","detail":"Tượng thần mạ vàng vận dụng kim thân trong lúc giao chiến với Tiểu Hồng và Bóng Lông. Dù có thể phục hồi tay cụt cùng vết thương, kim thân cuối cùng vẫn bị pháp khí Chân Thần áp chế.","thuocTinh":"Hộ thể và phục hồi","nguonGoc":"Tây Phương giáo","congNang":["Giúp tay cụt mọc lại và làm vết thương khép kín.","Gia trì cho thần thông Thiên thủ trong chiến đấu."],"nguoiTu":[{"ten":"Tượng thần mạ vàng","tuChuong":"@c0570","tangDatToi":"Có thể thi triển","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0570","loai":"thi triển","importance":"normal","giaiDoan":"Phục hồi kim thân","text":"Tượng thần mạ vàng dùng kim thân tái sinh tay cụt và khép lại vết thương trong cuộc giao chiến.","anchor":"tay cụt từ từ mọc lại, vết thương khép kín"}]},"capNhatToi":"@c0570","nguon":["@c0570"]},{"id":"ba-luc-chu-yem-chan-long-con-bang","name":"Ba lực Chu Yếm–Chân Long–Côn Bằng","cn":"","loai":"than-thong","loaiLabel":"Thần thông dung hợp","phamCap":"Không rõ","hePhai":"Chu Yếm, Chân Long và Côn Bằng","soHuu":["Bóng Lông"],"blurb":"Pháp môn dung hợp ba loại lực lượng của Bóng Lông để tạo đòn công kích mạnh.","detail":"Bóng Lông hợp nhất lực Chu Yếm, Chân Long và Côn Bằng, khiến toàn thân phát ánh sáng vạn trượng rồi đánh thẳng vào ma vân của cường giả Thiên quốc.","thuocTinh":"Dung hợp ba loại thần lực","uyLuc":"Được dùng để đánh tan hình thái đại ma của cường giả Thiên quốc.","dacDiem":"Ba loại lực lượng được hợp nhất trong cùng một trạng thái chiến đấu.","congNang":["Dung hợp lực Chu Yếm, Chân Long và Côn Bằng để công kích."],"nguoiTu":[{"ten":"Bóng Lông","tuChuong":"@c0571","tangDatToi":"Thi triển ba lực hợp nhất","trangThai":"đang tu luyện"}],"capNhatToi":"@c0571","tabs":{"tienTrinh":[{"chuong":"@c0571","loai":"thi triển","importance":"normal","giaiDoan":"Ba lực hợp nhất","text":"Bóng Lông dung hợp lực Chu Yếm, Chân Long và Côn Bằng để đánh vào ma vân của cường giả Thiên quốc.","anchor":"Thời khắc này, nó ba lực hợp nhất, Chu yếm, Chân long, Côn bằng dung hợp lại cùng với nhau"}]},"nguon":["@c0571"]},{"id":"nghi-thuc-huyet-te-thien-dia","name":"Nghi thức huyết tế thiên địa","cn":"","aliases":[],"loai":"bi-thuat","loaiLabel":"Nghi thức phá giới","phamCap":"Không rõ","hePhai":"Không rõ","soHuu":["Người áo bào tro","Người áo xám","Nhóm người chủ trì huyết tế"],"blurb":"Nghi thức dùng máu, hồn lực và tinh hoa sinh mệnh của hơn ngàn vạn người cùng vô số sinh linh để khai thông con đường giữa hạ giới và thượng giới.","detail":"Nghi thức được vận hành qua tế đàn huyết tế Hồng vực. Cái giá là sinh mệnh và hồn phách của một lượng vật tế cực lớn.","thuocTinh":"Huyết tế, phá giới","yeuCau":"Cần lượng lớn sinh mệnh, máu huyết, hồn lực và tinh hoa sinh mệnh làm vật tế.","uyLuc":"Có thể mở thông đạo nối hạ giới với thượng giới.","dacDiem":"Đòi hỏi cuộc hiến tế sinh linh ở quy mô cực lớn.","congNang":["Hấp thu máu, hồn lực và tinh hoa sinh mệnh để mở thông đạo giữa hai giới."],"nguoiTu":[{"ten":"Nhóm người chủ trì huyết tế","tuChuong":"@c0573","tangDatToi":"Có thể vận hành nghi thức tại tế đàn Hồng vực","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0573","loai":"xuất hiện","importance":"normal","giaiDoan":"Kích hoạt tế đàn phá giới","text":"Nghi thức hiến tế hơn ngàn vạn người cùng vô số sinh linh để khai thông con đường nối với thượng giới.","anchor":"Dùng sinh mệnh và máu huyết của ngàn vạn người làm vật tế lễ hiến tế cho ma đàn kia, chỉ vì để khai thông với thượng giới, triệu hoán Thần vô thượng, mở ra một con đường."}]},"capNhatToi":"@c0573","nguon":["@c0573"]},{"id":"dai-tran-tuyet-the-trong-co-dien","name":"Đại trận tuyệt thế trong cổ điện","cn":"","aliases":[],"loai":"khac","loaiLabel":"Trận pháp phòng hộ","phamCap":"Không rõ","hePhai":"Không rõ","soHuu":["Các giáo chủ trong cổ điện"],"blurb":"Đại trận bảo vệ cổ điện thượng giới nơi các giáo chủ mở thông đạo. Trận pháp vẫn không thể ngăn hoàn toàn thiên đao do thiên ý giáng xuống.","detail":"Khi nghi thức phá giới dẫn tới phản phệ, thiên đao chém xuyên sự bảo vệ của đại trận và làm cung điện tổn hại.","thuocTinh":"Phòng hộ","uyLuc":"Có khả năng bảo vệ cổ điện nhưng không ngăn được thiên đao của thiên ý.","congNang":["Bảo vệ cổ điện và những người tiến hành nghi thức phá giới."],"tabs":{"tienTrinh":[{"chuong":"@c0573","loai":"thi triển","importance":"normal","giaiDoan":"Chống thiên ý phản phệ","text":"Đại trận bảo vệ cổ điện nhưng bị thiên đao xuyên phá, khiến một phần cung điện tổn hại.","anchor":"Nên biết, nơi đây được bố trí đại trận tuyệt thế, nhưng vẫn bị chém nát, cung điện bị tổn hại."}]},"capNhatToi":"@c0573","nguon":["@c0573"]},{"id":"thuat-chien-thien-y","name":"Thuật chiến thiên ý","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Thần thông hợp lực","phamCap":"Không rõ","hePhai":"Thượng giới","soHuu":["Những tồn tại chống thiên ý ở thượng giới"],"blurb":"Thần thông hợp lực dùng để can thiệp thiên phạt và quy tắc, cưỡng ép mở đường từ thượng giới xuống hạ giới.","detail":"Những tồn tại trong cung điện cổ ở thượng giới cùng triển khai thuật này để quấy nhiễu thiên phạt và hoàn thành chuyến giáng lâm. Người thi triển phải chịu phản phệ, thổ huyết và không thể tiếp tục dùng lại thủ đoạn ấy.","thuocTinh":"Can thiệp thiên phạt và quy tắc vượt giới","yeuCau":"Cần nhiều tồn tại thượng giới hợp lực","uyLuc":"Có thể cưỡng ép mở đường vượt giới trong lúc thiên phạt giáng xuống.","dacDiem":"Người thi triển chịu phản phệ nặng và cơ hội triển khai không thể lặp lại.","congNang":["Quấy nhiễu thiên phạt và cưỡng ép mở đường vượt giới @c0574"],"nguoiTu":[{"ten":"Những tồn tại chống thiên ý ở thượng giới","tuChuong":"@c0574","tangDatToi":"Không rõ","trangThai":"Đã thi triển"}],"trangThai":"Không thể tiếp tục triển khai","capNhatToi":"@c0574","tabs":{"tienTrinh":[{"chuong":"@c0574","loai":"thi triển","importance":"normal","giaiDoan":"Hợp lực mở đường vượt giới","text":"Được triển khai để chống thiên ý và mở đường đưa các sinh linh xuống hạ giới, khiến những người thi triển chịu phản phệ.","anchor":"Chiến thiên ý, quả nhiên gặp phải phạn phệ, cũng không bao giờ có thể triển khai được nữa"}]},"nguon":["@c0574"]},{"id":"sat-tran-vung-nui","name":"Sát trận vùng núi","cn":"","loai":"khac","loaiLabel":"Trận pháp sát phạt","phamCap":"Không rõ","hePhai":"Không rõ","soHuu":["Thạch Hạo"],"blurb":"Sát trận từng được dùng phục kích Thạch Hạo, sau đó được Đả Thần Thạch bố trí lại và tăng cường bằng thần liệu.","detail":"Khi Thạch Hạo mở toàn bộ trận pháp, quần sơn rung động và sát quang đánh thẳng vào ba cường giả đã nhen Thần hỏa, nhưng cả ba vẫn thoát ra mà không bị thương.","uyLuc":"Khi mở hoàn toàn có thể khiến quần sơn rung động và sát quang sôi trào.","dacDiem":"Được Đả Thần Thạch hoàn thiện và tăng cường bằng thần liệu.","congNang":["Tạo sát quang công kích những mục tiêu tiến vào vùng trận pháp."],"tabs":{"tienTrinh":[{"chuong":"@c0577","loai":"thi triển","importance":"normal","giaiDoan":"Mở toàn lực","text":"Thạch Hạo mở toàn bộ sát trận để đối phó ba cường giả đã nhen Thần hỏa nhưng không thể làm họ bị thương.","anchor":"nơi này có một tòa sát trận phát ra ánh sáng vô lượng, giết thẳng về ba Thần"}]},"capNhatToi":"@c0577","nguon":["@c0577"]},{"id":"bi-phap-thieu-dot-tinh-huyet-cua-xuyen-son-giap","name":"Bí pháp thiêu đốt tinh huyết của Xuyên sơn giáp","cn":"","loai":"bi-thuat","loaiLabel":"Bí pháp","phamCap":"Không rõ","hePhai":"Xuyên sơn giáp","soHuu":["Xuyên sơn giáp màu bạc"],"blurb":"Bí pháp đánh đổi tinh huyết và tiềm năng sinh mệnh để gia tăng tốc độ chạy trốn.","detail":"Xuyên sơn giáp thi triển bí pháp khi bị tràng vực của tế đàn truy sát. Phương pháp này giúp nó tăng tốc bằng cách thiêu đốt máu huyết và tiêu hao tiềm năng sinh mệnh.","thuocTinh":"Thiêu đốt tinh huyết","yeuCau":"Tiêu hao tinh huyết và tiềm năng sinh mệnh","congNang":["Tăng tốc độ chạy trốn bằng cách tiêu hao tiềm năng sinh mệnh."],"dacDiem":"Đem tiềm năng sinh mệnh đổi lấy tốc độ trong tình thế nguy cấp.","nguoiTu":[{"ten":"Xuyên sơn giáp màu bạc","tuChuong":"@c0579","tangDatToi":"","trangThai":"đã thi triển"}],"trangThai":"Đã xuất hiện","capNhatToi":"@c0579","tabs":{"tienTrinh":[{"chuong":"@c0579","loai":"thi triển","importance":"normal","giaiDoan":"Thiêu đốt tinh huyết","text":"Xuyên sơn giáp tiêu hao tinh huyết và tiềm năng sinh mệnh để tăng tốc chạy khỏi tràng vực của tế đàn.","anchor":"tiêu hao tiềm năng của sinh mệnh để tăng nhanh tốc độ chạy trốn"}]},"nguon":["@c0579"]},{"id":"thien-phu-thong-linh","name":"Thiên phú Thông linh","cn":"","loai":"bi-thuat","loaiLabel":"Thiên phú tiên đoán","phamCap":"Không rõ","hePhai":"Vũ tộc","soHuu":["Vũ Tử Mạch"],"blurb":"Thiên phú cho phép Vũ Tử Mạch nhìn một phần quá khứ và tương lai.","detail":"Khi dò xét Thạch Hạo, Vũ Tử Mạch chỉ thấy tương lai hỗn độn và quá khứ hư vô, đồng thời bị phản phệ khiến mi tâm nứt và chảy máu.","thuocTinh":"Thông linh, tiên đoán","yeuCau":"Thiên phú của Vũ Tử Mạch","uyLuc":"Có thể nhìn một phần tương lai và quá khứ của đối tượng.","dacDiem":"Việc dò xét Thạch Hạo gây phản phệ ở mi tâm.","congNang":["Nhìn một phần tương lai và quá khứ của đối tượng @c0580"],"nguoiTu":[{"ten":"Vũ Tử Mạch","tuChuong":"@c0580","tangDatToi":"Không rõ","trangThai":"đang sử dụng"}],"capNhatToi":"@c0580","tabs":{"tienTrinh":[{"chuong":"@c0580","loai":"thi triển","importance":"normal","giaiDoan":"Dò xét Thạch Hạo","text":"Vũ Tử Mạch dùng thiên phú Thông linh nhìn quá khứ và tương lai của Thạch Hạo nhưng bị phản phệ.","anchor":"mi tâm xuất hiện một vết nứt rồi tràn ra một tia máu"}]},"nguon":["@c0580"]},{"id":"ao-nghia-sat-luc-cua-thien-quoc","name":"Áo nghĩa sát lục của Thiên quốc","cn":"","aliases":[],"loai":"kiem-quyet","loaiLabel":"Kiếm quyết","phamCap":"","hePhai":"Thiên quốc","soHuu":["Ngân Dực"],"blurb":"Kiếm quyết sát phạt của Thiên quốc được Ngân Dực thi triển trong trận chiến tại di chỉ Bổ Thiên các.","detail":"Người thi triển kết kiếm quyết, phát ra kiếm khí cùng những phù văn kỳ lạ dày đặc trong hư không. Các phù văn lao tới nhằm trói buộc và hủy diệt binh khí của đối thủ.","thuocTinh":"Sát lục","congNang":["Phát kiếm khí và phù văn để trói buộc, công kích binh khí của đối thủ."],"nguoiTu":[{"ten":"Ngân Dực","tuChuong":"@c0582","tangDatToi":"","trangThai":"thi triển"}],"tabs":{"tienTrinh":[{"chuong":"@c0582","loai":"thi triển","importance":"normal","giaiDoan":"Giao chiến tại di chỉ Bổ Thiên các","text":"Ngân Dực thi triển toàn bộ áo nghĩa sát lục để điều khiển kiếm khí và phù văn công kích kiếm gãy.","anchor":"Hắn nắm kiếm quyết chém về trước, thể hiện ra toàn bộ áo nghĩa sát lục của Thiên quốc"}]},"capNhatToi":"@c0582","nguon":["@c0582"]},{"id":"thuat-an-sat-cua-thien-quoc","name":"Thuật ẩn sát của Thiên quốc","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Thần thông ám sát","phamCap":"","hePhai":"Thiên quốc","soHuu":["Ngân Dực"],"blurb":"Thủ đoạn ám sát cho phép Ngân Dực che giấu thân hình trong hư không và bất ngờ tập kích mục tiêu.","detail":"Ngân Dực dùng ánh sáng chói mắt quấy nhiễu linh giác rồi biến mất trong hư không. Đòn tập kích đánh trúng vị trí Thạch Hạo vừa rời khỏi nhưng không bắt được mục tiêu.","thuocTinh":"Ẩn nấp và ám sát","congNang":["Ẩn người trong hư không để tiếp cận và tập kích mục tiêu."],"nguoiTu":[{"ten":"Ngân Dực","tuChuong":"@c0582","tangDatToi":"","trangThai":"thi triển"}],"tabs":{"tienTrinh":[{"chuong":"@c0582","loai":"thi triển","importance":"normal","giaiDoan":"Ám sát Thạch Hạo","text":"Ngân Dực ẩn vào hư không để tập kích Thạch Hạo nhưng chỉ đánh trúng tàn ảnh.","anchor":"Ngân Dực biến mất trong hư không, không hề thấy hình bóng đâu nữa"}]},"capNhatToi":"@c0582","nguon":["@c0582"]},{"id":"nghi-thuc-huyet-te-trieu-hoi-than-ma","name":"Nghi thức huyết tế triệu hồi Thần ma","cn":"","aliases":[],"loai":"bi-thuat","loaiLabel":"Bí thuật","phamCap":"Không rõ","hePhai":"Thiên quốc","soHuu":["Ngân Dực"],"blurb":"Bí pháp huyết tế được Ngân Dực thi triển khi liều mạng chống Quỷ gia.","detail":"Người thi triển đốt tinh huyết, điều khiển tế đàn và tập hợp oán khí cùng linh hồn từ huyết tế để ngưng tụ những Thần ma màu máu. Việc sử dụng khiến thân thể Ngân Dực khô quắt.","thuocTinh":"Huyết tế và triệu hồi","nguonGoc":"Thiên quốc","yeuCau":"Thiêu đốt tinh huyết và sử dụng tế đàn cùng linh hồn huyết tế","uyLuc":"Triệu hồi nhiều bóng Thần ma màu máu vây công đối thủ.","dacDiem":"Việc thi triển gây tổn hao tinh huyết nghiêm trọng.","congNang":["Triệu hồi Thần ma từ oán khí và linh hồn huyết tế."],"nguoiTu":[{"ten":"Ngân Dực","tuChuong":"@c0583","tangDatToi":"Thi triển liều mạng","trangThai":"Đã thi triển"}],"tabs":{"tienTrinh":[{"chuong":"@c0583","loai":"thi triển","importance":"normal","giaiDoan":"Thiêu đốt tinh huyết","text":"Ngân Dực thiêu đốt tinh huyết và dùng tế đàn triệu hồi các Thần ma màu máu chống Quỷ gia.","anchor":"hắn đốt cháy máu trong lòng, tiến hành một nghi thức quái lạ"}]},"trangThai":"Đã được thi triển","capNhatToi":"@c0583","nguon":["@c0583"]},{"id":"kiem-gioi-cua-quy-gia","name":"Kiếm giới của Quỷ gia","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Kiếm đạo thần thông","phamCap":"Không rõ","hePhai":"Kiếm đạo","soHuu":["Quỷ gia"],"blurb":"Kiếm đạo thần thông giúp Quỷ gia diễn hóa một kiếm thành cả một thế giới.","detail":"Một kiếm của Quỷ gia hóa thành thế giới, quét sạch các bóng Thần ma và toàn bộ hiện tượng huyết sắc do Ngân Dực triệu hồi.","thuocTinh":"Kiếm đạo","uyLuc":"Diệt sạch các Thần ma được triệu hồi bằng huyết tế.","dacDiem":"Kiếm không còn biểu hiện như kiếm khí thông thường mà diễn hóa thành một thế giới.","congNang":["Diễn hóa một kiếm thành thế giới để trấn áp và quét sạch công kích."],"nguoiTu":[{"ten":"Quỷ gia","tuChuong":"@c0583","tangDatToi":"Mức cực cao","trangThai":"Đã thi triển"}],"tabs":{"tienTrinh":[{"chuong":"@c0583","loai":"thi triển","importance":"normal","giaiDoan":"Một kiếm thành giới","text":"Quỷ gia diễn hóa một kiếm thành thế giới và quét sạch các Thần ma huyết tế.","anchor":"không còn là kiếm khí nữa mà là một thế giới do kiếm biến thành"}]},"trangThai":"Đã được thi triển","capNhatToi":"@c0583","nguon":["@c0583"]},{"id":"sat-kiem-thien-quoc","name":"Sát kiếm Thiên quốc","cn":"","aliases":[],"loai":"kiem-quyet","loaiLabel":"Kiếm pháp sát thủ","phamCap":"Không rõ","hePhai":"Thiên quốc","soHuu":[],"blurb":"Kiếm pháp sát thủ của Thiên quốc từng được chấp niệm mạnh nhất của Quỷ gia mô phỏng.","detail":"Chấp niệm của Quỷ gia mô phỏng Sát kiếm Thiên quốc để phong giữ tàn hồn. Vì mối liên hệ này, lão chỉ thức tỉnh khi gặp lại bí pháp của Thiên quốc.","thuocTinh":"Sát phạt","nguonGoc":"Thiên quốc","dacDiem":"Bản mô phỏng của kiếm pháp có thể được dùng để trấn phong tàn hồn.","congNang":["Được chấp niệm của Quỷ gia mô phỏng để phong giữ tàn hồn."],"tabs":{"tienTrinh":[{"chuong":"@c0583","loai":"nhắc tới","importance":"normal","giaiDoan":"Hé lộ liên hệ","text":"Quỷ gia tiết lộ chấp niệm mạnh nhất của mình từng mô phỏng Sát kiếm Thiên quốc để phong giữ tàn hồn.","anchor":"một tia chấp niệm mạnh mẽ nhất của ta đã mô phỏng theo sát kiếm của Thiên quốc"}]},"trangThai":"Được nhắc tới","capNhatToi":"@c0583","nguon":["@c0583"]},{"id":"con-bang-phap-hinh-nguoi","name":"Côn Bằng pháp hình người","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Bảo thuật","phamCap":"Không rõ","hePhai":"Côn Bằng","soHuu":["Thạch Hạo"],"blurb":"Hình thái chiến đấu Côn Bằng được Thạch Hạo vận dụng khi đối đầu Thần linh Ma Quỳ viên.","detail":"Thạch Hạo hóa thành Côn Bằng hình người, nhanh chóng tiêu hao dược lực chưa hấp thu hết và chuyển hóa nguồn lực ấy thành thần năng phục vụ chiến đấu.","thuocTinh":"Biến hóa và chiến đấu","yeuCau":"Vận dụng pháp môn Côn Bằng","uyLuc":"Hỗ trợ Thạch Hạo giao chiến trực diện với Thần linh Ma Quỳ viên.","dacDiem":"Dùng hình thái Côn Bằng hình người để tăng tốc tiêu hao và chuyển hóa dược lực.","congNang":["Chuyển hóa nhanh dược lực còn tồn đọng thành thần năng chiến đấu."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0583","tangDatToi":"Thi triển hình người","trangThai":"Đang tu luyện"}],"tabs":{"tienTrinh":[{"chuong":"@c0583","loai":"thi triển","importance":"normal","giaiDoan":"Côn Bằng hình người","text":"Thạch Hạo hóa thành Côn Bằng hình người để chuyển hóa dược lực còn sót thành thần năng.","anchor":"Nó hóa thành một con Côn bằng hình người, điên cuồng tiêu hao dòng dược lực này"}]},"trangThai":"Đang được Thạch Hạo sử dụng","capNhatToi":"@c0583","nguon":["@c0583"]},{"id":"bao-thuat-luan-hoi","name":"Bảo thuật Luân hồi","aliases":["Luân hồi của Chí Tôn cốt"],"cn":"","loai":"than-thong","loaiLabel":"Bảo thuật Chí Tôn cốt","phamCap":"Không rõ","hePhai":"Chí Tôn cốt","soHuu":["Thạch Hạo"],"blurb":"Bảo thuật do Chí Tôn cốt phát huy, có thể khiến mục tiêu nhanh chóng già yếu và suy kiệt.","detail":"Khi được thần lực đầy đủ tẩm bổ, phù văn của Chí Tôn cốt hóa thành các lò luyện khóa cường giả Ma Quỳ viên, khiến thân thể hắn héo gầy và tinh khí thần suy giảm nghiêm trọng.","thuocTinh":"Luân hồi","uyLuc":"Có hiệu lực với cường giả đã nhen nhóm Thần hỏa khi được cung cấp đủ thần lực.","dacDiem":"Phù văn khóa mục tiêu rồi làm quá trình già yếu diễn ra nhanh chóng.","congNang":["Làm mục tiêu già yếu, thân thể héo gầy và tinh khí thần suy kiệt. @c0584"],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0584","tangDatToi":"Thi triển thành công","trangThai":"dang-tu"}],"trangThai":"Đang được Thạch Hạo sử dụng","capNhatToi":"@c0584","tabs":{"tienTrinh":[{"chuong":"@c0584","loai":"thi triển","importance":"normal","giaiDoan":"Thi triển thành công","text":"Thạch Hạo dùng bảo thuật Luân hồi khóa cường giả Ma Quỳ viên và khiến đối phương nhanh chóng già yếu, suy kiệt.","anchor":"lúc này nhanh chóng già yếu, thân thể héo gầy, tinh khí thần giảm sút nghiêm trọng"}]},"nguon":["@c0584"]},{"id":"cam-thuat-ma-quy-vien","name":"Cấm thuật Ma Quỳ viên","cn":"","loai":"bi-thuat","loaiLabel":"Cấm thuật","phamCap":"Không rõ","hePhai":"Ma Quỳ viên","soHuu":["Người đàn ông áo đen của Ma Quỳ viên"],"blurb":"Cấm thuật cho phép người thi triển khai thông thiên địa và mượn sức mạnh từ mặt trời để quyết tử với đối thủ.","detail":"Cường giả Ma Quỳ viên vận dụng cấm thuật trong bản thể hoa hướng dương đen, dẫn thần mang và sức mạnh mặt trời xuống. Người thi triển phải trả giá rất lớn.","thuocTinh":"Mặt trời","yeuCau":"Người thi triển phải trả giá lớn.","uyLuc":"Mượn sức mạnh thiên địa và mặt trời để phá hủy địch thủ.","dacDiem":"Là thủ đoạn quyết tử của cường giả Ma Quỳ viên.","congNang":["Khai thông thiên địa và dẫn sức mạnh mặt trời xuống công kích đối thủ. @c0584"],"nguoiTu":[{"ten":"Người đàn ông áo đen của Ma Quỳ viên","tuChuong":"@c0584","tangDatToi":"Có thể thi triển","trangThai":"nguoi-tu-da-tu-vong"}],"trangThai":"Người thi triển đã tử vong","capNhatToi":"@c0584","tabs":{"tienTrinh":[{"chuong":"@c0584","loai":"thi triển","importance":"normal","giaiDoan":"Quyết tử","text":"Cường giả Ma Quỳ viên dùng cấm thuật khai thông thiên địa và mượn sức mạnh vô thượng để đối phó Thạch Hạo.","anchor":"khai thông thiên địa mượn tới sức mạnh vô thượng để phá hủy địch thủ"}]},"nguon":["@c0584"]},{"id":"nguyen-thuy-chan-giai-sieu-thoat","name":"Nguyên thủy chân giải – Siêu thoát","cn":"","loai":"cong-phap","loaiLabel":"Kinh văn","phamCap":"Bất hủ theo lời truyền","hePhai":"Cung điện Chí Tôn","soHuu":["Cung điện Chí Tôn"],"blurb":"Bản kinh thuộc Cung điện Chí Tôn, được tương truyền là phần Siêu thoát của Nguyên thủy chân giải.","detail":"Hoàng Vũ cho biết Cung điện Chí Tôn nắm giữ bản kinh Siêu thoát và bản kinh này được xưng là bất hủ.","thuocTinh":"Kinh văn","nguonGoc":"Cung điện Chí Tôn","dacDiem":"Được xưng là bất hủ.","congNang":[],"nguoiTu":[],"trangThai":"Được lưu truyền tại Cung điện Chí Tôn","capNhatToi":"@c0585","tabs":{"tienTrinh":[{"chuong":"@c0585","loai":"xuất hiện","importance":"normal","giaiDoan":"Được Hoàng Vũ nhắc tới","text":"Hoàng Vũ tiết lộ Cung điện Chí Tôn có bản Siêu thoát của Nguyên thủy chân giải và bản kinh được xưng là bất hủ.","anchor":"Tương truyền, Cung điện Chí Tôn có bản trung của Nguyên thủy chân giải – Siêu thoát, được xưng bất hủ"}]},"nguon":["@c0585"]},{"id":"co-kinh-phan-than-chu-thu","name":"Cổ kinh phân thân chủ–thứ","cn":"","loai":"cong-phap","loaiLabel":"Cổ kinh","phamCap":"Không rõ","hePhai":"Bổ Thiên giáo","soHuu":["Nguyệt Thiền tiên tử"],"blurb":"Cổ kinh do một đại nhân trẻ tuổi của Tiên điện truyền cho Bổ Thiên giáo, sau đó được bí mật đưa xuống hạ giới và rơi vào tay Nguyệt Thiền.","detail":"Kinh văn được dùng để tu luyện phân thân chủ–thứ, hướng tới trạng thái bất tử bất diệt. Kết quả tu luyện của Nguyệt Thiền chưa được xác nhận.","thuocTinh":"Phân thân chủ–thứ","nguonGoc":"Do đại nhân trẻ tuổi của Tiên điện truyền cho Bổ Thiên giáo.","yeuCau":"Không rõ","uyLuc":"Có mục tiêu tu luyện phân thân chủ–thứ để mưu cầu bất tử bất diệt.","dacDiem":"Kinh văn được bí mật đưa từ Bổ Thiên giáo xuống hạ giới.","chieuTieuBieu":[],"cacTang":[],"trangThai":"Đang do Nguyệt Thiền nghiên cứu","congNang":["Tu luyện phân thân chủ–thứ, hướng tới bất tử bất diệt."],"nguoiTu":[{"ten":"Nguyệt Thiền tiên tử","tuChuong":"@c0586","tangDatToi":"Chưa rõ","trangThai":"Chưa rõ thành công"}],"tabs":{"tienTrinh":[{"chuong":"@c0586","loai":"xuất hiện","importance":"normal","giaiDoan":"Lộ nguồn gốc và mục đích","text":"Cổ kinh được tiết lộ là do đại nhân trẻ tuổi của Tiên điện truyền cho Bổ Thiên giáo, sau đó rơi vào tay Nguyệt Thiền để nàng tu luyện phân thân chủ–thứ.","anchor":"nàng muốn tu luyện ra phân thân chủ thứ hòng bất tử bất diệt, cũng không biết có thành công hay không"}]},"capNhatToi":"@c0586","nguon":["@c0586"]},{"id":"kiem-y-tu-nua-quyen-da-thu","name":"Kiếm ý từ nửa quyển da thú","cn":"","aliases":[],"loai":"kiem-quyet","loaiLabel":"Kiếm ý","phamCap":"Nửa bộ","hePhai":"Truyền thừa trong quyển da thú","soHuu":["Thạch Hạo"],"blurb":"Kiếm ý do Thạch Hạo tu thành từ một quyển da thú chứa tiểu thế giới bí ẩn. Pháp môn có thể dung hợp nhiều loại bảo thuật thành phù văn kiếm ý công kích, nhưng Thạch Hạo mới chỉ tu thành nửa bộ và chưa mở được thế giới bên trong quyển da thú.","detail":"Thạch Hạo dung hợp kiếm cỏ với lực lượng Côn Bằng và Toan Nghê, cô đọng thành phù văn kiếm ý để công kích. Hoàng Vũ nhận ra pháp môn bắt nguồn từ quyển da thú bí ẩn và xác định Thạch Hạo mới tu thành nửa bộ, chưa mở được tiểu thế giới ẩn chứa bên trong; đồng thời liên hệ quyển da thú với bí thiên mang hai chữ “Lục đạo”. @c0587","thuocTinh":"Kiếm ý","nguonGoc":"Quyển da thú chứa tiểu thế giới bí ẩn","yeuCau":"Chưa rõ","uyLuc":"Có thể dung hợp nhiều loại bảo thuật thành một phù văn công kích mạnh.","dacDiem":"Thạch Hạo mới tu thành nửa bộ và chưa mở được tiểu thế giới bên trong quyển da thú. @c0587","chieuTieuBieu":["Kiếm ý dung hợp kiếm cỏ, Côn Bằng và Toan Nghê"],"cacTang":[{"ten":"Nửa bộ Kiếm ý","moTa":"Phần Kiếm ý Thạch Hạo đã tu thành từ quyển da thú.","chuong":"@c0587"}],"trangThai":"Đang được Thạch Hạo tu luyện","nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0587","tangDatToi":"Nửa bộ","trangThai":"Đang tu luyện"}],"congNang":["Dung hợp kiếm cỏ cùng lực lượng Côn Bằng và Toan Nghê thành phù văn kiếm ý công kích."],"tabs":{"tienTrinh":[{"chuong":"@c0587","loai":"hé lộ tầng-chiêu","importance":"major","giaiDoan":"Lộ nguồn gốc nửa bộ","text":"Hoàng Vũ nhận ra Thạch Hạo đã tu thành nửa bộ Kiếm ý từ quyển da thú nhưng chưa mở được thế giới bên trong.","anchor":"ngươi từng chiếm được một quyển da thú cho nên mới tu thành nửa bộ tên là Kiếm ý"}]},"capNhatToi":"@c0587","nguon":["@c0587"]},{"id":"tien-hac-tung-canh","name":"Tiên hạc tung cánh","cn":"","loai":"than-thong","loaiLabel":"Đại thần thông","phamCap":"Không rõ","hePhai":"Tộc tiên hạc","soHuu":["Hoàng Vũ"],"blurb":"Đại thần thông được Hoàng Vũ thi triển sau khi hiện bản thể tiên hạc.","detail":"Thần thông tạo ra ánh sáng hoàng kim có thể phá núi thành tro và dùng cánh tiên hạc xuyên thủng thế phòng ngự của đối thủ.","thuocTinh":"Ánh sáng hoàng kim và công kích bằng cánh","uyLuc":"Những luồng sáng do thần thông tạo ra đủ sức phá núi thành tro.","dacDiem":"Được thi triển bằng bản thể tiên hạc.","chieuTieuBieu":["Tiên hạc tung cánh"],"congNang":["Tạo ánh sáng hoàng kim để công kích và dùng cánh xuyên phá phòng ngự tại @c0588."],"nguoiTu":[{"ten":"Hoàng Vũ","tuChuong":"@c0588","tangDatToi":"Có thể thi triển bằng bản thể","trangThai":"đang sử dụng"}],"trangThai":"đang lưu truyền","capNhatToi":"@c0588","tabs":{"tienTrinh":[{"chuong":"@c0588","loai":"thi triển","importance":"normal","giaiDoan":"Hiện bản thể tiên hạc","text":"Hoàng Vũ thi triển Tiên hạc tung cánh, phá thế phòng ngự và đánh Thạch Hạo ho ra máu.","anchor":"đây chính là đại thần thông của tộc này, danh xứng với thực - Tiên hạc tung cánh"}]},"nguon":["@c0588"]},{"id":"phap-tac-hoang-kim","name":"Pháp tắc hoàng kim","cn":"","loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Không rõ","hePhai":"Bộ tộc Tiên hạc","soHuu":["Hoàng Vũ"],"blurb":"Thần thông tạo ra hàng loạt cột vàng chạm phù văn để vây kín và công kích mục tiêu.","detail":"Hoàng Vũ triển khai những cột vàng đỉnh thiên lập địa nhằm giam Thạch Hạo. Sức ép khiến Thạch Hạo bị đánh đến thất khiếu chảy máu và phải huyết tế nhiều pháp khí Chân thần để mở đường thoát.","thuocTinh":"Hoàng kim","congNang":["Dựng cột vàng giam giữ và công kích mục tiêu tại @c0589."],"nguoiTu":[{"ten":"Hoàng Vũ","tuChuong":"@c0589","tangDatToi":"Không rõ","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c0589","loai":"thi triển","importance":"normal","giaiDoan":"Dùng trong cuộc truy sát","text":"Hoàng Vũ dựng hàng loạt cột vàng vây kín Thạch Hạo, buộc đối phương huyết tế pháp khí Chân thần để phá vây.","anchor":"Hoàng loạt cây cột màu vàng xuất hiện, đỉnh thiên lập địa"}]},"capNhatToi":"@c0589","nguon":["@c0589"]},{"id":"co-che-ap-che-canh-gioi-cua-dien-vo-truong","name":"Cơ chế áp chế cảnh giới của diễn võ trường","cn":"","loai":"khac","loaiLabel":"Trận pháp","phamCap":"Không rõ","hePhai":"Tổ địa Hỏa quốc","soHuu":[],"blurb":"Cơ chế trong diễn võ trường có thể áp chế cảnh giới của người tiến vào.","detail":"Khi linh thân Hoàng Vũ bước vào sân, cảnh giới của lão bị áp chế và ưu thế tuyệt đối trước Thạch Hạo biến mất. Nhờ đó Thạch Hạo có thể áp đảo rồi dùng kiếm gãy xuyên thủng mi tâm linh thân.","congNang":["Áp chế cảnh giới của sinh linh tiến vào diễn võ trường tại @c0589."],"tabs":{"tienTrinh":[{"chuong":"@c0589","loai":"xuất hiện","importance":"normal","giaiDoan":"Kích hoạt trong trận quyết chiến","text":"Cơ chế trong diễn võ trường áp chế cảnh giới của linh thân Hoàng Vũ, tạo điều kiện để Thạch Hạo phản công.","anchor":"Hả, nơi này bị áp chế cảnh giới!"}]},"capNhatToi":"@c0589","nguon":["@c0589"]},{"id":"te-song","name":"Tế sống","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Thần thông hiến tế","phamCap":"Không rõ","hePhai":"Mười Động thiên","soHuu":["Thạch Hạo"],"blurb":"Tế sống là thần thông hiến tế lấy chính người thi triển làm mồi dẫn, thiêu đốt mười Động thiên để kéo mục tiêu vào thế bị tế sống. Thủ đoạn này đủ sức đe dọa một Thần linh đã nhen nhóm Thần hỏa, nhưng cũng đặt sinh mệnh người thi triển vào thế hủy diệt.","detail":"Thạch Hạo từng lấy bản thân làm mồi dẫn, thiêu đốt mười Động thiên và nối chúng thành lao tù, qua đó ép Động thiên của Hoàng Vũ hiển hóa rồi bốc cháy, kéo đối phương vào thế tế sống. Đây là thủ đoạn có thể đe dọa sinh linh đã nhen nhóm Thần hỏa, song người thi triển cũng đồng thời tự đẩy mình vào cửa tử nhất sinh. @c0590","thuocTinh":"Hiến tế","yeuCau":"Lấy bản thân làm mồi dẫn và thiêu đốt mười Động thiên","uyLuc":"Có thể đe dọa một Thần linh đã nhen nhóm Thần hỏa.","dacDiem":"Người thi triển đồng thời tự đặt sinh mệnh vào thế hủy diệt.","chieuTieuBieu":["Thiêu đốt mười Động thiên để tế sống bản thân và mục tiêu"],"congNang":["Lấy chính người thi triển làm mồi dẫn để kéo mục tiêu vào thế tế sống. @c0590","Thiêu đốt và nối mười Động thiên thành lao tù, ép Động thiên của mục tiêu hiển hóa rồi bốc cháy. @c0590"],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0590","tangDatToi":"Đã thi triển","trangThai":"đang-tu"}],"trangThai":"Đã được Thạch Hạo thi triển","capNhatToi":"@c0590","tabs":{"tienTrinh":[{"chuong":"@c0590","loai":"thi triển","importance":"major","giaiDoan":"Thiêu đốt mười Động thiên","text":"Thạch Hạo lấy bản thân làm mồi dẫn, thiêu đốt mười Động thiên để kéo Hoàng Vũ vào thế tế sống.","anchor":"Dùng bản thân làm mồi dẫn để tế sống hòng giết chết đối phương!"}]},"nguon":["@c0590"]},{"id":"tinh-hoa-nguyen-rua-tu-gi-tien-dien","name":"Tinh hoa nguyền rủa từ gỉ Tiên điện","cn":"","aliases":[],"loai":"bi-thuat","loaiLabel":"Đại thuật sát sinh","phamCap":"Không rõ","hePhai":"Tiên điện","soHuu":["Hoàng Vũ"],"blurb":"Đại thuật sát sinh được Hoàng Vũ kích hoạt trước lúc chết nhằm triệt đường sống của Thạch Hạo.","detail":"Tinh hoa nguyền rủa được luyện từ mảnh gỉ bóc khỏi Tiên điện bằng đồng. Quy tắc của thuật hòa vào huyết nhục Thạch Hạo và liên tục phá hoại thân thể vừa được cành liễu ghép lại.","thuocTinh":"Nguyền rủa","nguonGoc":"Được luyện từ gỉ bóc khỏi Tiên điện bằng đồng.","uyLuc":"Quy tắc nguyền rủa tiếp tục phá hủy thân thể Thạch Hạo sau khi Hoàng Vũ đã chết.","dacDiem":"Có thể được kích hoạt bằng chút thần thức còn lại của người thi triển.","congNang":["Đưa quy tắc nguyền rủa vào huyết nhục và liên tục phá hủy thân thể mục tiêu."],"nguoiTu":[{"ten":"Hoàng Vũ","tuChuong":"@c0591","tangDatToi":"Có thể thi triển trước lúc chết","trangThai":"tu-vong"}],"trangThai":"Đã thi triển","capNhatToi":"@c0591","tabs":{"tienTrinh":[{"chuong":"@c0591","loai":"thi triển","importance":"normal","giaiDoan":"Đòn nguyền rủa cuối cùng","text":"Hoàng Vũ dùng chút thần thức cuối cùng kích hoạt tinh hoa nguyền rủa luyện từ gỉ Tiên điện, khiến quy tắc của thuật hòa vào cơ thể Thạch Hạo.","anchor":"Dùng khối gỉ sét bóc từ Tiên điện bằng đồng để luyện chế thành tinh hoa nguyền rủa"}]},"nguon":["@c0591"]},{"id":"phu-nguyen-rua-tu-gi-tien-dien-bang-dong","name":"Phù nguyền rủa từ gỉ Tiên điện bằng đồng","cn":"","aliases":[],"loai":"bi-thuat","loaiLabel":"Nguyền rủa","phamCap":"Không rõ","hePhai":"Tiên điện","soHuu":["Tiên điện"],"blurb":"Phù nguyền rủa màu xanh loang lổ được luyện từ gỉ của Tiên điện bằng đồng, bám vào xương cốt và liên tục phá hoại cơ thể người trúng.","detail":"Một đại nhân Tiên điện luyện nguyền rủa này từ gỉ của Tiên điện bằng đồng. Phù văn bám trên xương cốt Thạch Hạo, tiếp tục ăn mòn thân thể dù cậu đã hấp thu tinh hoa sinh mệnh từ cành liễu.","thuocTinh":"Nguyền rủa ăn mòn","nguonGoc":"Được một đại nhân Tiên điện luyện từ gỉ của Tiên điện bằng đồng.","uyLuc":"Tiếp tục phá hoại thân thể và xương cốt, khiến thương thế không thể trị tận gốc.","dacDiem":"Phù văn màu xanh loang lổ bám trên xương cốt người trúng.","trangThai":"Đang tác động lên Thạch Hạo","capNhatToi":"@c0592","congNang":["Ăn mòn thân thể và xương cốt của người trúng nguyền rủa @c0592"],"nguoiTu":[],"tabs":{"tienTrinh":[{"chuong":"@c0592","loai":"xuất hiện","importance":"normal","giaiDoan":"Nguyền rủa tiếp tục phát tác","text":"Phù nguyền rủa bám trên xương cốt Thạch Hạo và tiếp tục phá hoại cơ thể bất chấp sinh cơ từ cành liễu.","anchor":"Đây là phù nguyền rủa mà một vị đại nhân của Tiên điện đã luyện hóa từ gỉ sắt từ Tiên điện bằng đồng mà thành"}]},"nguon":["@c0592"]},{"id":"thuat-phong-an-than-luc-cua-thach-hao","name":"Thuật phong ấn thần lực của Thạch Hạo","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Thần thông phong ấn","phamCap":"Chưa rõ","hePhai":"Chưa rõ","soHuu":["Thạch Hạo"],"blurb":"Thuật phong ấn được Thạch Hạo dùng để khóa sức mạnh của đối phương.","detail":"Thạch Hạo dồn thần lực phong ấn Tôn giả Bất Lão sơn, khiến một thân sức mạnh của đối phương tạm thời không thể vận dụng.","thuocTinh":"Phong ấn","uyLuc":"Có thể tạm thời khiến sức mạnh của Tôn giả trở thành hư vô.","dacDiem":"Thần lực được dồn vào mục tiêu để khóa sức mạnh.","congNang":["Phong ấn sức mạnh của đối phương, khiến mục tiêu tạm thời không thể vận dụng tu vi."],"nguoiTu":[{"ten":"Thạch Hạo","tuChuong":"@c0593","tangDatToi":"Chưa rõ","trangThai":"đang sử dụng"}],"trangThai":"Đang được sử dụng","capNhatToi":"@c0593","tabs":{"tienTrinh":[{"chuong":"@c0593","loai":"thi triển","importance":"normal","giaiDoan":"Phong ấn Tôn giả Bất Lão sơn","text":"Thạch Hạo thi triển thuật phong ấn, tạm thời khóa toàn bộ sức mạnh có thể vận dụng của Tôn giả.","anchor":"Thạch Hạo ấn tay một cái, thần lực dân trào phong ấn lại tên Tôn giả kia"}]},"nguon":["@c0593"]},{"id":"bang-trao-mau-vang","name":"Bằng trảo màu vàng","cn":"","aliases":[],"loai":"than-thong","loaiLabel":"Thần thông","phamCap":"Không rõ","hePhai":"Bằng tộc","soHuu":["Bằng Cửu"],"blurb":"Thần thông do Bằng Cửu thi triển, hóa ra móng vuốt vàng khổng lồ để công kích và bắt giữ đối thủ.","detail":"Bằng Cửu dùng Bằng trảo màu vàng đánh gãy bảo cụ gậy gỗ của bà lão Tần tộc rồi bắt giữ bà ta.","thuocTinh":"Công kích và bắt giữ","uyLuc":"Có thể đánh gãy bảo cụ gậy gỗ trong một kích.","dacDiem":"Hóa thành móng vuốt lớn màu vàng hạ xuống mục tiêu.","chieuTieuBieu":["Bằng trảo màu vàng"],"congNang":["Công kích, phá hủy bảo cụ và bắt giữ mục tiêu."],"nguoiTu":[{"ten":"Bằng Cửu","tuChuong":"@c0595","tangDatToi":"Có thể thi triển","trangThai":"Đang sử dụng"}],"trangThai":"Đang lưu truyền","capNhatToi":"@c0595","tabs":{"tienTrinh":[{"chuong":"@c0595","loai":"thi triển","importance":"normal","giaiDoan":"Bằng Cửu thi triển","text":"Bằng Cửu thi triển móng vuốt vàng, đánh gãy gậy gỗ và bắt giữ bà lão Tần tộc.","anchor":"Bằng trảo màu vàng hạ xuống đánh gãy cây gậy gỗ kia rồi bắt lấy bà ta"}]},"nguon":["@c0595"]},{"id":"chu-tuoc-niet-ban-phap","name":"Chu Tước Niết bàn pháp","cn":"","loai":"bi-thuat","loaiLabel":"Pháp môn Niết bàn","phamCap":"","hePhai":"Hỏa Quốc","soHuu":["Thạch Hạo"],"blurb":"Pháp môn Niết bàn có nguồn gốc từ Hỏa Quốc, được Thạch Hạo vận dụng sau lần tái tạo chân thân đầu tiên. (+) Pháp môn Dục hỏa trùng sinh của Hỏa Quốc, được dùng trong lần chữa trị cuối cùng cho Thạch Hạo. [CAN-SOAT-GOP]","detail":"Lão Vương gia Hỏa Quốc giao pháp môn này để phối hợp với Ngũ hành Niết bàn pháp và Chân Hoàng Niết bàn pháp. Ba pháp Niết bàn cùng được thi triển nhưng vẫn không thể cứu Thạch Hạo khỏi thương thế và nguyền rủa.","nguon":["@c0598","@c0619"],"tabs":{}},{"id":"chan-hoang-niet-ban-phap","name":"Chân Hoàng Niết bàn pháp","cn":"","loai":"bi-thuat","loaiLabel":"Pháp môn Niết bàn","phamCap":"","hePhai":"Bộ tộc Hồng Hoàng","soHuu":["Hồng Hoàng","Thạch Hạo"],"blurb":"Bí pháp Niết bàn bất truyền của bộ tộc Hồng Hoàng, có khả năng chữa thương và tái sinh.","detail":"Hồng Hoàng phá lệ đem pháp môn này trao đổi để cứu Thạch Hạo. Nó được phối hợp với Ngũ hành Niết bàn pháp và Chu Tước Niết bàn pháp, song lần chữa trị cuối cùng vẫn thất bại.","nguon":["@c0598"]}]};